-- ════════════════════════════════════════════════════════
-- 239 — Huitième recensement : treize maisons des catalogues
--       (lots d'écriture 01 à 03)
-- ────────────────────────────────────────────────────────
-- D'OÙ ELLES VIENNENT. Le huitième recensement part du marché : les
-- noms vendus par cigares.com, cigarworld.de, Neptune, Holt's et
-- Atlantic, absents de l'atlas — 322 à trier. Chaque nom passe par le
-- tri, le contradicteur (qui roule, où, à la main, encore en activité),
-- le rédacteur, la relecture et la traduction. Voici les treize
-- premières fiches :
--   Rép. dominicaine  Baron Ullmann (usine propre, ville non dite),
--                     Belmore (von Eicken, Santiago), Bock y Ca. (ABAM,
--                     Villa Mella), Capadura (Don Esteban, Santiago),
--                     Chateau Diadem (usine propre, Navarrete),
--                     Notorious (MJ Frias, Tamboril), Simon Beltre
--                     (atelier familial, Azua), Vallejuelo (Intercigar,
--                     Tamboril)
--   Honduras          Stauffenberg (La Pequeña Vega, Danlí)
--   Indonésie         El Gaucho (Besuki Raya, Jember)
--   Nicaragua         Alfambra, Casa de Alegria, Don Fidel (Estelí)
--
-- ── CE QUE LA CONTRADICTION A CORRIGÉ ───────────────────
-- Alfambra est la maison d'Alejandro Mata (Málaga, atelier d'Estelí
-- en 2007, marque en 2015). Belmore se roule chez von Eicken, l'ancienne
-- Charles Fairmorn de Santiago. Bock y Ca. garde sa fiche malgré le
-- rachat par Villiger : son histoire commence à La Havane en 1865, avant
-- lui — le précédent est Cuesta-Rey.
--
-- ── CE QUE LA RELECTURE A TRANCHÉ ───────────────────────
-- Rough Rider n'entre pas : Jochy Blanco possède la marque et la
-- fabrique qui la roule, c'est une ligne de Tabacalera Palma (elle y
-- viendra par les ajouts). Rosa Nicaragua (Casa de Alegria) et Vedado
-- Flat Black (Don Fidel) vont en `mentions` (238). Aucune note de presse
-- n'est reprise. L'incendie de Tamboril (septembre 2022) est raconté
-- comme dans la fiche William Ventura, sans deviner où Vallejuelo se
-- roule depuis. Alfambra a été relue contre Cigar Journal (11 janvier
-- 2023).
--
-- ── CE QUE LES GARDE-FOUS ONT REFUSÉ ────────────────────
-- marques_check : sept fiches nommaient Cigar Journal ou Cigar
-- Aficionado comme source d'un fait (72 phrases dans les six langues).
-- La revue n'était qu'un canal : le fait reste, l'URL reste dans
-- `source`, la parole revient à qui l'a dite (« dit Alejandro Mata ») ;
-- les forces qu'elle prêtait aux cigares sortent. coherence_check :
-- « fondée en » datait deux fabriques tierces (Charles Fairmorn pour
-- Belmore, MJ Frias pour Notorious), désormais « établie » et
-- « ouverte ». Bock y Ca. perd ses renvois écrits dans le texte.
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Chateau Diadem : 2020 ou 2022. Belmore : production 2001, marque
-- 2003. El Legado (Don Fidel) : cape H2000 ou Habano selon le revendeur.
--
-- Rejouable : INSERT … ON DUPLICATE KEY UPDATE ; le `brands` des pays
-- touchés est relu en base et réécrit en littéral ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── Baron Ullmann ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Baron Ullmann',
        'dominican',
        'Non précisée — G. von Ullmann, F. Diaz Suarez',
        'Usine propre — Baron Ullmann & Frandisuarez, ville non précisée (République dominicaine)',
        'cigarworld.de « Baron Ullmann: Buy Cigars » (date non précisée : fondateurs Georg Baron von Ullmann et Francisco Diaz Suarez, achat d''une fabrique en République dominicaine, cape Cameroun et tripe dominicaine/nicaraguayenne, lignes Corona et Gran Robusto Edición Limitada) ; opencorporates.com « Fundacion Baron Von Ullman Frandisuarez » (date non précisée : enregistrement de la société en République dominicaine) ; lastdodo.com « Baron Ullmann Frandisuarez Cigars Corp Inc – hand made » (date non précisée : confirme la raison sociale et la mention hand made) ; trademarks.justia.com « Baron Von Ullmann & Frandisuarez Corp., S.A. » (date non précisée : dépôts de marque de la société, lecture intégrale bloquée) ; tabak-kontor.de « Cigars & Cigarillos Baron Ullmann » (date non précisée : revendeur confirmant la commercialisation actuelle, production en petite série depuis une vingtaine d''années, longtemps réservée à des cadeaux)',
        NULL,
        'Georg Baron von Ullmann junior, héritier de la famille de banquiers allemande Sal. Oppenheim (dit le site cigarworld.de), et son associé Francisco Diaz Suarez ont acheté une fabrique en République dominicaine pour y faire rouler à la main un cigare né, selon la maison, d''une idée personnelle avant de devenir un projet commercial. La société est enregistrée en République dominicaine sous le nom Baron Von Ullmann & Frandisuarez Corp., S.A. (Justia Trademarks, opencorporates.com), et vend ses cigares depuis, selon un caviste allemand, une vingtaine d''années — longtemps réservés à des cadeaux avant d''entrer dans le commerce. La ville de la fabrique n''est précisée par aucune des sources trouvées.

Le catalogue courant associe une cape du Cameroun à une sous-cape et une tripe de République dominicaine et du Nicaragua (cigarworld.de). Deux lignes sont documentées : la Corona et la Gran Robusto Edición Limitada. La marque est distribuée en Allemagne par plusieurs cavistes indépendants.',
        '[{"name":"Corona","color":"#A0522D","force":null,"wrapper":"Cameroun","vitolas":[],"story":"Cape camerounaise sur tripe dominicaine et nicaraguayenne, dit cigarworld.de."},{"name":"Gran Robusto Edición Limitada","color":"#A0522D","force":null,"wrapper":"Cameroun","vitolas":[],"story":"Édition limitée du même assemblage, en format gran robusto, dit le revendeur."}]',
        'Georg Baron von Ullmann junior, heir to the German banking family Sal. Oppenheim (according to the website cigarworld.de), and his partner Francisco Diaz Suarez bought a factory in the Dominican Republic to have a cigar hand-rolled there that was born, according to the house, from a personal idea before it became a commercial venture. The company is registered in the Dominican Republic under the name Baron Von Ullmann & Frandisuarez Corp., S.A. (Justia Trademarks, opencorporates.com), and has, according to a German tobacconist, been selling its cigars for around twenty years — long reserved for gifts before entering the trade. The town where the factory stands is not given by any of the sources found.

The current range pairs a Cameroon wrapper with a Dominican and Nicaraguan binder and filler (cigarworld.de). Two lines are documented: the Corona and the Gran Robusto Edición Limitada. The brand is distributed in Germany by several independent tobacconists.',
        '[{"name":"Corona","color":"#A0522D","force":null,"wrapper":"Cameroon","vitolas":[],"story":"Cameroon wrapper over Dominican and Nicaraguan filler, according to cigarworld.de."},{"name":"Gran Robusto Edición Limitada","color":"#A0522D","force":null,"wrapper":"Cameroon","vitolas":[],"story":"A limited edition of the same blend, in Gran Robusto format, according to the retailer."}]',
        'Georg Baron von Ullmann junior, heredero de la familia alemana de banqueros Sal. Oppenheim (según el sitio cigarworld.de), y su socio Francisco Diaz Suarez compraron una fábrica en la República Dominicana para hacer liar allí a mano un puro nacido, según la casa, de una idea personal antes de convertirse en un proyecto comercial. La sociedad está registrada en la República Dominicana bajo el nombre Baron Von Ullmann & Frandisuarez Corp., S.A. (Justia Trademarks, opencorporates.com), y vende sus puros desde hace, según un comerciante alemán de puros, una veintena de años — reservados durante mucho tiempo a los regalos antes de entrar en el comercio. Ninguna de las fuentes encontradas precisa la ciudad de la fábrica.

El catálogo actual combina una capa de Camerún con un capote y una tripa de la República Dominicana y Nicaragua (cigarworld.de). Dos líneas están documentadas: la Corona y la Gran Robusto Edición Limitada. La marca se distribuye en Alemania a través de varios comerciantes independientes.',
        '[{"name":"Corona","color":"#A0522D","force":null,"wrapper":"Camerún","vitolas":[],"story":"Capa camerunesa sobre tripa dominicana y nicaragüense, según cigarworld.de."},{"name":"Gran Robusto Edición Limitada","color":"#A0522D","force":null,"wrapper":"Camerún","vitolas":[],"story":"Edición limitada de la misma liga, en formato Gran Robusto, según el revendedor."}]',
        'Georg Baron von Ullmann junior, Erbe der deutschen Bankiersfamilie Sal. Oppenheim (laut der Website cigarworld.de), und sein Partner Francisco Diaz Suarez kauften eine Fabrik in der Dominikanischen Republik, um dort von Hand eine Zigarre rollen zu lassen, die nach Angaben des Hauses aus einer persönlichen Idee entstand, bevor sie zu einem kommerziellen Projekt wurde. Das Unternehmen ist in der Dominikanischen Republik unter dem Namen Baron Von Ullmann & Frandisuarez Corp., S.A. eingetragen (Justia Trademarks, opencorporates.com) und verkauft seine Zigarren seit, nach Angaben eines deutschen Zigarrenhändlers, etwa zwanzig Jahren — lange Zeit nur als Geschenk gedacht, bevor sie in den Handel kamen. Die Stadt der Fabrik wird von keiner der gefundenen Quellen genannt.

Das aktuelle Sortiment verbindet ein Kamerun-Deckblatt mit einem dominikanischen und nicaraguanischen Umblatt und einer entsprechenden Einlage (cigarworld.de). Zwei Linien sind belegt: die Corona und die Gran Robusto Edición Limitada. Die Marke wird in Deutschland von mehreren unabhängigen Zigarrenhändlern vertrieben.',
        '[{"name":"Corona","color":"#A0522D","force":null,"wrapper":"Kamerun","vitolas":[],"story":"Kamerun-Deckblatt über dominikanischer und nicaraguanischer Einlage, laut cigarworld.de."},{"name":"Gran Robusto Edición Limitada","color":"#A0522D","force":null,"wrapper":"Kamerun","vitolas":[],"story":"Limitierte Edition derselben Mischung im Format Gran Robusto, laut dem Händler."}]',
        '小格奥尔格·冯·乌尔曼男爵——德国银行世家萨尔·奥彭海姆（Sal. Oppenheim）的后人（据 cigarworld.de 网站介绍）——与合伙人弗朗西斯科·迪亚斯·苏亚雷斯在多米尼加共和国购置了一家工厂，在那里手工卷制一款雪茄。据该品牌介绍，这款雪茄最初只是一个私人构想，后来才变成商业项目。公司在多米尼加共和国以 Baron Von Ullmann & Frandisuarez Corp., S.A. 之名注册（见 Justia Trademarks、opencorporates.com），据一位德国雪茄经销商介绍，其雪茄已售卖约二十年——长期以来只作礼品赠送，后来才进入商业流通。查到的资料均未说明工厂所在的城市。

现行产品线将喀麦隆茄衣与多米尼加共和国及尼加拉瓜的茄套、茄芯相配（cigarworld.de）。有据可查的系列共两款：Corona 与 Gran Robusto Edición Limitada。该品牌在德国由多家独立雪茄经销商经销。',
        '[{"name":"Corona","color":"#A0522D","force":null,"wrapper":"喀麦隆","vitolas":[],"story":"喀麦隆茄衣包裹多米尼加与尼加拉瓜茄芯，据 cigarworld.de 介绍。"},{"name":"Gran Robusto Edición Limitada","color":"#A0522D","force":null,"wrapper":"喀麦隆","vitolas":[],"story":"同一配方的限量版，规格为 Gran Robusto，据经销商介绍。"}]',
        'جورج بارون فون أولمان الابن، وريث أسرة المصرفيين الألمانية سال أوبنهايم (بحسب موقع cigarworld.de)، وشريكه فرانسيسكو دياث سواريث، اشتريا مصنعًا في جمهورية الدومينيكان ليُلفّ فيه باليد سيجار وُلد، بحسب الدار، من فكرة شخصية قبل أن يصير مشروعًا تجاريًا. والشركة مسجَّلة في جمهورية الدومينيكان باسم Baron Von Ullmann & Frandisuarez Corp., S.A. (بحسب Justia Trademarks وopencorporates.com)، وتبيع سيجارها منذ، بحسب تاجر سيجار ألماني، نحو عشرين عامًا — كانت طويلًا مخصَّصة للهدايا قبل أن تدخل التجارة. ولا تحدّد أيٌّ من المصادر التي عُثر عليها مدينة المصنع.

يجمع الكتالوج الحالي بين غلاف كاميروني ورباط وحشوة من جمهورية الدومينيكان ونيكاراغوا (cigarworld.de). وثمّة خطّان موثَّقان: كورونا وGran Robusto Edición Limitada. وتُوزَّع العلامة في ألمانيا عبر عدّة تجّار مستقلّين.',
        '[{"name":"Corona","color":"#A0522D","force":null,"wrapper":"الكاميرون","vitolas":[],"story":"غلاف كاميروني فوق حشوة دومينيكية ونيكاراغوية، بحسب cigarworld.de."},{"name":"Gran Robusto Edición Limitada","color":"#A0522D","force":null,"wrapper":"الكاميرون","vitolas":[],"story":"إصدار محدود من الخلطة نفسها، بقياس Gran Robusto، بحسب البائع."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Belmore ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Belmore',
        'dominican',
        '2001 (production) / 2003 (marque lancée)',
        'Chez Tabacalera von Eicken S.R.L. (ex-Charles Fairmorn), Santiago (République dominicaine)',
        'cigarworld.de « Belmore: Buy Cigars » (date non précisée : marque de Charles Fairmorn, production à Santiago depuis 2001, lancement commercial en 2003, lignes Belmore Connecticut et Belmore Maduro) ; cigarslover.com « Belmore Maduro Robusto » (date non précisée : roulage à l''usine Charles Fairmorn, Santiago) ; halfwheel.com « Kristoff Tres Compadres Toro » (date non précisée : la fabrique Charles Fairmorn S.A., fondée 2000-2001 à Santiago, est aujourd''hui Tabacalera von Eicken S.R.L., qui roule aussi Kristoff) ; ebony.com « How A Trip To The Dominican Republic Inspired The Creation Of This Black-Owned Cigar Brand » (date non précisée : Epic Cigars roulée par Tabacalera von Eicken, fabrique parfois dite Charles Fairmorn) ; rauchr.de « Charles Fairmorn: Buy Cigars Online » (date non précisée : origine 1972 aux États-Unis, antenne allemande à Hambourg puis Dingelstädt et Lübeck)',
        NULL,
        'Selon les pages du distributeur cigarworld.de, la maison Charles Fairmorn remonte à 1972 aux États-Unis, avant d''ouvrir une antenne allemande à Hambourg, puis à Dingelstädt (Thuringe) et à Lübeck ; ces mêmes pages disent la production des Belmore lancée en 2001 en République dominicaine, la marque étant commercialisée à partir de 2003. La presse spécialisée situe autrement l''origine de la fabrique dominicaine : halfwheel, à propos de Kristoff, y voit une société nommée Charles Fairmorn S.A., établie en 2000-2001 à Santiago, devenue depuis l''actuelle Tabacalera von Eicken S.R.L., qui roule aussi Kristoff et Epic Cigars. La continuité entre l''entité américaine de 1972 et cette fabrique n''est démontrée par aucune des sources de presse consultées.

Le catalogue documenté compte deux lignes : la Belmore Connecticut (ex-Clasico), cape Connecticut Shade américaine et tripe dominicaine et nicaraguayenne, dite légère par le distributeur, et la Belmore Maduro, cape maduro brésilienne à la saveur dite sucrée. La marque reste au catalogue de plusieurs revendeurs, sans actualité récente de la presse spécialisée qui lui soit propre.',
        '[{"name":"Belmore Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (États-Unis)","vitolas":[],"story":"Anciennement nommée Clasico, tripe dominicaine et nicaraguayenne, dite légère par le distributeur."},{"name":"Belmore Maduro","color":"#4A3728","force":null,"wrapper":"Maduro brésilien","vitolas":[],"story":"Cape brésilienne à la saveur dite sucrée par le distributeur."}]',
        'According to the pages of the distributor cigarworld.de, the house Charles Fairmorn dates back to 1972 in the United States, before opening a German branch in Hamburg, then in Dingelstädt (Thuringia) and in Lübeck; the same pages state that production of the Belmore began in 2001 in the Dominican Republic, with the brand marketed from 2003. The trade press places the origin of the Dominican factory differently: halfwheel, writing about Kristoff, identifies a company named Charles Fairmorn S.A., established in 2000-2001 in Santiago, which has since become the present-day Tabacalera von Eicken S.R.L., which also rolls Kristoff and Epic Cigars. The continuity between the 1972 American entity and this factory is not shown by any of the press sources consulted.

The documented range counts two lines: the Belmore Connecticut (formerly Clasico), an American Connecticut Shade wrapper with Dominican and Nicaraguan filler, described as mild by the distributor, and the Belmore Maduro, a Brazilian maduro wrapper with a flavour described as sweet. The brand remains in the catalogue of several retailers, with no recent coverage from the trade press specific to it.',
        '[{"name":"Belmore Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (United States)","vitolas":[],"story":"Formerly named Clasico, Dominican and Nicaraguan filler, described as mild by the distributor."},{"name":"Belmore Maduro","color":"#4A3728","force":null,"wrapper":"Brazilian Maduro","vitolas":[],"story":"Brazilian wrapper with a flavour described as sweet by the distributor."}]',
        'Según las páginas del distribuidor cigarworld.de, la casa Charles Fairmorn se remonta a 1972 en Estados Unidos, antes de abrir una filial alemana en Hamburgo, luego en Dingelstädt (Turingia) y en Lübeck; esas mismas páginas sitúan el lanzamiento de la producción de Belmore en 2001 en la República Dominicana, y la comercialización de la marca a partir de 2003. La prensa especializada sitúa de otro modo el origen de la fábrica dominicana: halfwheel, a propósito de Kristoff, identifica una sociedad llamada Charles Fairmorn S.A., establecida en 2000-2001 en Santiago, convertida desde entonces en la actual Tabacalera von Eicken S.R.L., que también lía Kristoff y Epic Cigars. Ninguna de las fuentes de prensa consultadas demuestra la continuidad entre la entidad estadounidense de 1972 y esta fábrica.

El catálogo documentado cuenta con dos líneas: la Belmore Connecticut (antes Clasico), capa Connecticut Shade estadounidense y tripa dominicana y nicaragüense, calificada de suave por el distribuidor, y la Belmore Maduro, capa maduro brasileña de sabor calificado de dulce. La marca sigue en el catálogo de varios revendedores, sin actualidad reciente propia en la prensa especializada.',
        '[{"name":"Belmore Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Estados Unidos)","vitolas":[],"story":"Anteriormente llamada Clasico, tripa dominicana y nicaragüense, calificada de suave por el distribuidor."},{"name":"Belmore Maduro","color":"#4A3728","force":null,"wrapper":"Maduro brasileño","vitolas":[],"story":"Capa brasileña de sabor calificado de dulce por el distribuidor."}]',
        'Den Seiten des Vertriebs cigarworld.de zufolge geht das Haus Charles Fairmorn auf das Jahr 1972 in den Vereinigten Staaten zurück, bevor es eine deutsche Niederlassung in Hamburg eröffnete, dann in Dingelstädt (Thüringen) und in Lübeck; dieselben Seiten geben an, die Produktion der Belmore sei 2001 in der Dominikanischen Republik angelaufen, die Marke ab 2003 vermarktet worden. Die Fachpresse verortet den Ursprung der dominikanischen Fabrik anders: halfwheel sieht, im Zusammenhang mit Kristoff, ein Unternehmen namens Charles Fairmorn S.A., ansässig seit 2000-2001 in Santiago, das seither zur heutigen Tabacalera von Eicken S.R.L. wurde, die auch Kristoff und Epic Cigars rollt. Die Kontinuität zwischen der amerikanischen Einheit von 1972 und dieser Fabrik wird von keiner der herangezogenen Pressequellen belegt.

Das belegte Sortiment umfasst zwei Linien: die Belmore Connecticut (früher Clasico), ein amerikanisches Connecticut-Shade-Deckblatt mit dominikanischer und nicaraguanischer Einlage, vom Vertrieb als mild bezeichnet, und die Belmore Maduro, ein brasilianisches Maduro-Deckblatt mit einem als süß bezeichneten Geschmack. Die Marke bleibt im Katalog mehrerer Händler, ohne dass die Fachpresse zuletzt eigens über sie berichtet hätte.',
        '[{"name":"Belmore Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Vereinigte Staaten)","vitolas":[],"story":"Früher Clasico genannt, dominikanische und nicaraguanische Einlage, vom Vertrieb als mild bezeichnet."},{"name":"Belmore Maduro","color":"#4A3728","force":null,"wrapper":"Brasilianisches Maduro","vitolas":[],"story":"Brasilianisches Deckblatt mit einem vom Vertrieb als süß bezeichneten Geschmack."}]',
        '据经销商 cigarworld.de 网站介绍，Charles Fairmorn 这一品牌可追溯至1972年的美国，此后在德国开设分支，先在汉堡，继而在丁格尔施泰特（图林根）和吕贝克；同一网站称 Belmore 的生产于2001年在多米尼加共和国启动，品牌自2003年起投入销售。专业媒体对这家多米尼加工厂的起源另有说法：halfwheel 在介绍 Kristoff 时提到一家名为 Charles Fairmorn S.A. 的公司，于2000至2001年间在圣地亚哥设立，此后演变为今天的 Tabacalera von Eicken S.R.L.，该厂也为 Kristoff 与 Epic Cigars 卷制雪茄。查阅过的媒体资料均未证实1972年那家美国公司与这家工厂之间的延续关系。

有据可查的产品线共两款：Belmore Connecticut（原名 Clasico），美国浅色康涅狄格茄衣配多米尼加与尼加拉瓜茄芯，经销商称其口感清淡；以及 Belmore Maduro，巴西马杜罗茄衣，风味据称偏甜。该品牌仍在多家经销商的目录中，但近来未见专业媒体对其本身的报道。',
        '[{"name":"Belmore Connecticut","color":"#C9A96E","force":"Mild","wrapper":"浅色康涅狄格（美国）","vitolas":[],"story":"原名 Clasico，多米尼加与尼加拉瓜茄芯，经销商称其口感清淡。"},{"name":"Belmore Maduro","color":"#4A3728","force":null,"wrapper":"巴西马杜罗","vitolas":[],"story":"巴西茄衣，风味经销商称之为偏甜。"}]',
        'بحسب صفحات الموزِّع cigarworld.de، تعود دار Charles Fairmorn إلى عام 1972 في الولايات المتحدة، قبل أن تفتح فرعًا ألمانيًا في هامبورغ، ثم في دينغلشتات (تورينغن) وفي لوبيك؛ وتقول الصفحات نفسها إنّ إنتاج Belmore انطلق عام 2001 في جمهورية الدومينيكان، وإنّ تسويق العلامة بدأ اعتبارًا من 2003. أمّا الصحافة المتخصّصة فتضع أصل المصنع الدومينيكي في موضع آخر: فموقع halfwheel، في معرض حديثه عن Kristoff، يرى شركة تُدعى Charles Fairmorn S.A.، أُنشئت بين 2000 و2001 في سانتياغو، وصارت منذ ذلك الحين Tabacalera von Eicken S.R.L. الحالية، التي تُلفّ أيضًا Kristoff وEpic Cigars. ولا يُثبت أيٌّ من مصادر الصحافة المُراجَعة استمرارية بين الكيان الأمريكي لعام 1972 وهذا المصنع.

يضمّ الكتالوج الموثَّق خطّين: Belmore Connecticut (المعروف سابقًا باسم Clasico)، غلاف كونيتيكت شيد أمريكي وحشوة دومينيكية ونيكاراغوية، يصفه الموزِّع بالخفيف؛ وBelmore Maduro، غلاف مادورو برازيلي بنكهة يوصف بأنها حلوة. وتبقى العلامة في كتالوجات عدّة بائعين، من دون أخبار حديثة خاصّة بها في الصحافة المتخصّصة.',
        '[{"name":"Belmore Connecticut","color":"#C9A96E","force":"Mild","wrapper":"كونيتيكت شيد (الولايات المتحدة)","vitolas":[],"story":"كانت تُعرف سابقًا باسم Clasico، حشوة دومينيكية ونيكاراغوية، يصفها الموزِّع بالخفيفة."},{"name":"Belmore Maduro","color":"#4A3728","force":null,"wrapper":"مادورو برازيلي","vitolas":[],"story":"غلاف برازيلي بنكهة يصفها الموزِّع بأنها حلوة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Bock y Ca. ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Bock y Ca.',
        'dominican',
        '1865 (Cuba) ; relance 1999 (Villiger)',
        'Chez ABAM Cigars S.R.L. (Matías Maragoto), Villa Mella, Santo Domingo Norte (République dominicaine)',
        'halfwheel.com « Villiger Celebrates 25 Years Of Bock y Ca. » (2024 : Villiger fête les vingt-cinq ans de la relance avec l''édition limitée Bock Renacimiento 25 Años, roulée par ABAM Cigars S.R.L. de Matías Maragoto) ; cigarjournal.com « ABAM Cigars: Villiger''s Unknown Factory » (date non précisée : usine ABAM à Santo Domingo, dirigée par le Cubain exilé Matías Maragoto depuis 1996 avec son frère José et son épouse Aidee ; marques roulées : Bock y Ca., La Flor de Ynclan, 1888, La Libertad, Corrida) ; cigaraficionado.com « Villiger Opens Factory In Nicaragua » (date non précisée : Villiger dispose par ailleurs de sa propre fabrique au Nicaragua, distincte d''ABAM) ; villigercigars.com « Celebrating 25 years of BOCK Y CA. cigars » (date non précisée, dit la maison Villiger : Gustav Bock Müller fonde El Águila de Oro à La Havane en 1865, la marque Bock attestée dès 1888, invention de la bague de cigare en 1880, relance en 1999 via la filiale El Mundo De Tabaco, modernisation en 2008) ; cigarworld.de « Bock y Ca.: Buy Cigars » (date non précisée : lignes Corona Tubo, Robusto, Panetela, Churchill et 25 Años Renacimiento Toro Gordo ; sous-cape indonésienne, tripe dominicaine et nicaraguayenne, profil medium)',
        NULL,
        'Selon le blog de Villiger, l''Allemand Gustav Bock Müller (1837-1910), émigré à Cuba, fonde à La Havane en 1865 la manufacture El Águila de Oro ; le nom Bock, attesté sur une marque dès 1888, lui reste attaché, et Villiger le crédite de l''invention de la bague de cigare en 1880. La marque décline après la mort de Bock en 1910 et s''éteint comme maison cubaine. Heinrich Villiger la redécouvre et la relance en 1999 comme cigare dominicain, via sa filiale El Mundo De Tabaco, et la maison situe une modernisation de la marque en 2008. Depuis, Bock y Ca. est roulée chez ABAM Cigars S.R.L., fabrique dirigée par le Cubain exilé Matías Maragoto, installé en République dominicaine depuis 1996 avec son frère José et son épouse Aidee, dans la zone franche industrielle de Villa Mella, à Santo Domingo Norte — l''usine qui roule aussi, pour Villiger, La Flor de Ynclan, 1888, La Libertad et Corrida.

En 2024, Villiger a fêté les vingt-cinq ans de la relance avec l''édition limitée Bock Renacimiento 25 Años, roulée par ABAM (halfwheel). Le catalogue courant compte, selon cigarworld.de, les vitolas Corona Tubo, Robusto, Panetela et Churchill, à sous-cape indonésienne et tripe dominicaine et nicaraguayenne, décrites comme un cigare medium à la douceur crémeuse typique de la République dominicaine (Villiger).',
        '[{"name":"Bock y Ca.","color":"#A0522D","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Sous-cape indonésienne et tripe dominicaine et nicaraguayenne, dite douce et crémeuse par Villiger."},{"name":"Bock Renacimiento 25 Años","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Édition limitée en format Toro Gordo pour les vingt-cinq ans de la relance, en 2024 (halfwheel)."}]',
        'According to Villiger''s blog, the German Gustav Bock Müller (1837-1910), who emigrated to Cuba, founded the El Águila de Oro factory in Havana in 1865; the name Bock, attested on a brand from 1888, stayed attached to him, and Villiger credits him with inventing the cigar band in 1880. The brand declined after Bock''s death in 1910 and died out as a Cuban house. Heinrich Villiger rediscovered it and relaunched it in 1999 as a Dominican cigar, through his subsidiary El Mundo De Tabaco, and the house places a modernisation of the brand in 2008. Since then, Bock y Ca. has been rolled at ABAM Cigars S.R.L., a factory run by the exiled Cuban Matías Maragoto, settled in the Dominican Republic since 1996 with his brother José and his wife Aidee, in the Villa Mella industrial free-trade zone, in Santo Domingo Norte — the factory that also rolls, for Villiger, La Flor de Ynclan, 1888, La Libertad and Corrida.

In 2024, Villiger celebrated the twenty-fifth anniversary of the relaunch with the limited edition Bock Renacimiento 25 Años, rolled by ABAM (halfwheel). The current range comprises, according to cigarworld.de, the Corona Tubo, Robusto, Panetela and Churchill vitolas, with an Indonesian binder and Dominican and Nicaraguan filler, described as a medium cigar with the creamy sweetness typical of the Dominican Republic (Villiger).',
        '[{"name":"Bock y Ca.","color":"#A0522D","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Indonesian binder and Dominican and Nicaraguan filler, described by Villiger as sweet and creamy."},{"name":"Bock Renacimiento 25 Años","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A limited edition in Toro Gordo format for the twenty-fifth anniversary of the relaunch, in 2024 (halfwheel)."}]',
        'Según el blog de Villiger, el alemán Gustav Bock Müller (1837-1910), emigrado a Cuba, funda en La Habana en 1865 la fábrica El Águila de Oro; el nombre Bock, atestiguado en una marca desde 1888, queda unido a él, y Villiger le atribuye la invención de la anilla del puro en 1880. La marca decae tras la muerte de Bock en 1910 y se extingue como casa cubana. Heinrich Villiger la redescubre y la relanza en 1999 como puro dominicano, a través de su filial El Mundo De Tabaco, y la casa sitúa una modernización de la marca en 2008. Desde entonces, Bock y Ca. se lía en ABAM Cigars S.R.L., fábrica dirigida por el cubano exiliado Matías Maragoto, instalado en la República Dominicana desde 1996 con su hermano José y su esposa Aidee, en la zona franca industrial de Villa Mella, en Santo Domingo Norte — la fábrica que también lía, para Villiger, La Flor de Ynclan, 1888, La Libertad y Corrida.

En 2024, Villiger celebró los veinticinco años del relanzamiento con la edición limitada Bock Renacimiento 25 Años, liada por ABAM (halfwheel). El catálogo actual cuenta, según cigarworld.de, con las vitolas Corona Tubo, Robusto, Panetela y Churchill, con capote indonesio y tripa dominicana y nicaragüense, descritas como un puro medium con la dulzura cremosa típica de la República Dominicana (Villiger).',
        '[{"name":"Bock y Ca.","color":"#A0522D","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Capote indonesio y tripa dominicana y nicaragüense, calificada por Villiger de dulce y cremosa."},{"name":"Bock Renacimiento 25 Años","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Edición limitada en formato Toro Gordo por los veinticinco años del relanzamiento, en 2024 (halfwheel)."}]',
        'Laut dem Blog von Villiger gründete der Deutsche Gustav Bock Müller (1837-1910), nach Kuba ausgewandert, 1865 in Havanna die Fabrik El Águila de Oro; der Name Bock, ab 1888 auf einer Marke belegt, blieb mit ihm verbunden, und Villiger schreibt ihm die Erfindung der Zigarrenbauchbinde im Jahr 1880 zu. Die Marke verfiel nach Bocks Tod 1910 und erlosch als kubanisches Haus. Heinrich Villiger entdeckte sie wieder und brachte sie 1999 über seine Tochtergesellschaft El Mundo De Tabaco als dominikanische Zigarre neu heraus; das Haus verortet eine Modernisierung der Marke im Jahr 2008. Seither wird Bock y Ca. bei ABAM Cigars S.R.L. gerollt, einer Fabrik unter Leitung des ins Exil gegangenen Kubaners Matías Maragoto, der seit 1996 mit seinem Bruder José und seiner Frau Aidee in der Dominikanischen Republik lebt, in der Industrie-Freihandelszone von Villa Mella, in Santo Domingo Norte — der Fabrik, die für Villiger auch La Flor de Ynclan, 1888, La Libertad und Corrida rollt.

2024 feierte Villiger die fünfundzwanzig Jahre seit der Neuauflage mit der limitierten Edition Bock Renacimiento 25 Años, gerollt bei ABAM (halfwheel). Das aktuelle Sortiment umfasst laut cigarworld.de die Formate Corona Tubo, Robusto, Panetela und Churchill, mit indonesischem Umblatt und dominikanischer und nicaraguanischer Einlage, beschrieben als mittelkräftige Zigarre mit der für die Dominikanische Republik typischen cremigen Süße (Villiger).',
        '[{"name":"Bock y Ca.","color":"#A0522D","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Indonesisches Umblatt und dominikanische sowie nicaraguanische Einlage, von Villiger als süß und cremig bezeichnet."},{"name":"Bock Renacimiento 25 Años","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Limitierte Edition im Format Toro Gordo zum fünfundzwanzigsten Jahrestag der Neuauflage, 2024 (halfwheel)."}]',
        '据 Villiger 的博客介绍，移居古巴的德国人古斯塔夫·博克·米勒（Gustav Bock Müller，1837-1910）于1865年在哈瓦那创立了 El Águila de Oro 卷烟厂；Bock 这个名字自1888年起便用作品牌名并与他联系在一起，Villiger 方面还将1880年发明雪茄环的功劳归于他。博克于1910年去世后，这一品牌逐渐式微，作为古巴品牌就此消失。海因里希·威利格重新发掘了这一名字，于1999年通过旗下子公司 El Mundo De Tabaco 将其作为多米尼加雪茄品牌重新推出，该品牌方面称其在2008年进行过一次品牌革新。此后，Bock y Ca. 一直在 ABAM Cigars S.R.L. 卷制，这家工厂由流亡古巴人马蒂亚斯·马拉戈托主持，他自1996年起携兄弟何塞与妻子艾迪定居多米尼加共和国，工厂位于圣多明各北区维拉梅拉的工业自由贸易区——这家工厂也为 Villiger 卷制 La Flor de Ynclan、1888、La Libertad 与 Corrida。

2024年，Villiger 以限量版 Bock Renacimiento 25 Años 庆祝品牌复兴二十五周年，该款由 ABAM 卷制（halfwheel）。据 cigarworld.de 介绍，现行产品线包括 Corona Tubo、Robusto、Panetela 与 Churchill 几种规格，印尼茄套配多米尼加与尼加拉瓜茄芯，被形容为一款中等浓度、带有多米尼加共和国典型奶油般甜润口感的雪茄（Villiger）。',
        '[{"name":"Bock y Ca.","color":"#A0522D","force":"Medium","wrapper":"未公开","vitolas":[],"story":"印尼茄套配多米尼加与尼加拉瓜茄芯，Villiger 称其甜美绵密。"},{"name":"Bock Renacimiento 25 Años","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"为纪念2024年品牌复兴二十五周年推出的限量版，规格为 Toro Gordo（halfwheel）。"}]',
        'بحسب مدوّنة Villiger، أسّس الألماني غوستاف بوك موللر (1837-1910)، الذي هاجر إلى كوبا، مصنع El Águila de Oro في هافانا سنة 1865؛ وظلّ اسم Bock، الموثَّق على علامة منذ 1888، مرتبطًا به، وتنسب إليه Villiger اختراع حلقة السيجار سنة 1880. تراجعت العلامة بعد وفاة بوك سنة 1910 وانطفأت كدار كوبية. وأعاد هاينريش فيليغر اكتشافها فأطلقها من جديد سنة 1999 سيجارًا دومينيكيًا، عبر فرعه El Mundo De Tabaco، وتضع الدار تحديثًا للعلامة سنة 2008. ومنذ ذلك الحين تُلفّ Bock y Ca. في ABAM Cigars S.R.L.، وهو مصنع يديره الكوبي المنفيّ ماتياس ماراغوتو، المقيم في جمهورية الدومينيكان منذ 1996 مع أخيه خوسيه وزوجته آيدي، في المنطقة الحرة الصناعية بفيّا ميّا، في سانتو دومينغو نورتي — وهو المصنع الذي يُلفّ أيضًا لصالح Villiger كلًّا من La Flor de Ynclan و1888 وLa Libertad وCorrida.

في 2024، احتفلت Villiger بمرور خمسة وعشرين عامًا على إعادة الإطلاق بإصدار محدود هو Bock Renacimiento 25 Años، لفّته ABAM (halfwheel). ويضمّ الكتالوج الحالي، بحسب cigarworld.de، قياسات Corona Tubo وRobusto وPanetela وChurchill، برباط إندونيسي وحشوة دومينيكية ونيكاراغوية، تُوصَف بأنها سيجار متوسط القوة بحلاوة كريمية معهودة في جمهورية الدومينيكان (Villiger).',
        '[{"name":"Bock y Ca.","color":"#A0522D","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"رباط إندونيسي وحشوة دومينيكية ونيكاراغوية، تصفها Villiger بأنها حلوة وكريمية."},{"name":"Bock Renacimiento 25 Años","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"إصدار محدود بقياس Toro Gordo بمناسبة مرور خمسة وعشرين عامًا على إعادة الإطلاق، سنة 2024 (halfwheel)."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Capadura ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Capadura',
        'dominican',
        'Non précisée — Oskar Nausch, Don Esteban',
        'Chez Tabacalera Don Esteban (Oskar Nausch), Santiago de los Caballeros (République dominicaine)',
        'cigarworld.de « Capadura: Buy Cigars » (date non précisée : présente Capadura comme la propre marque d''Oskar Nausch, roulée à la Tabacalera Don Esteban, Santiago de los Caballeros, collaboration vieille de près de vingt ans, distribution en Allemagne depuis juin 2021 après la Suisse et l''Autriche, dix variantes, tripe brésilienne, profil medium) ; eldiquetrading.com (portail fournisseur, date non précisée : la Tabacalera Don Esteban, dirigée par Oskar Nausch, roule aussi Samana, Cibao et de nombreuses marques privées pour des tiers) ; zigarrenwelt.de « Capadura: Buy Cigars » (date non précisée : Oskar Nausch, originaire de Wuppertal, installé en République dominicaine, fournit surtout la Suisse et l''Autriche)',
        NULL,
        'Oskar Nausch, originaire de Wuppertal (Allemagne) et installé depuis des années en République dominicaine, dirige la Tabacalera Don Esteban, une petite manufacture de Santiago de los Caballeros. Le caviste allemand cigarworld.de, qui travaille avec lui depuis près de vingt ans, présente Capadura comme sa propre marque, roulée à la main dans cette fabrique et distribuée en Allemagne depuis juin 2021 après des débuts en Suisse et en Autriche. Un portail fournisseur (eldiquetrading.com) situe cependant Capadura parmi les productions de Don Esteban aux côtés de Samana, Cibao et de nombreuses marques privées confectionnées pour des tiers, sans préciser si Capadura relève du même statut de marque privée ou d''une création propre à Nausch ; le rattachement exact — maison propre ou marque de catalogue confiée par un distributeur — n''est donc pas définitivement tranché par les sources trouvées.

Le catalogue en vente compte dix variantes selon cigarworld.de, dont la tripe associe des tabacs brésiliens ; le distributeur le présente comme équilibré, pour amateurs de cigares medium. Aucune ligne individuelle n''est documentée par nom, cape ou force dans les sources consultées ; la fiche s''en tient donc à cette description d''ensemble.',
        '[{"name":"Capadura","color":"#8B5A2B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Tripe brésilienne, décliné en dix vitolas, dit cigarworld.de."}]',
        'Oskar Nausch, originally from Wuppertal (Germany) and settled for years in the Dominican Republic, runs the Tabacalera Don Esteban, a small factory in Santiago de los Caballeros. The German tobacconist cigarworld.de, which has worked with him for nearly twenty years, presents Capadura as his own brand, hand-rolled at this factory and distributed in Germany since June 2021 after starting out in Switzerland and Austria. A supplier portal (eldiquetrading.com), however, places Capadura among Don Esteban''s productions alongside Samana, Cibao and numerous private-label brands made for third parties, without specifying whether Capadura holds the same private-label status or is a creation of Nausch''s own; the exact standing — a house in its own right or a catalogue brand entrusted by a distributor — is therefore not definitively settled by the sources found.

The range on sale comprises ten variants according to cigarworld.de, whose filler blends Brazilian tobaccos; the distributor presents it as balanced, for lovers of medium cigars. No individual line is documented by name, wrapper or strength in the sources consulted; this entry therefore keeps to this overall description.',
        '[{"name":"Capadura","color":"#8B5A2B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Brazilian filler, offered in ten vitolas, according to cigarworld.de."}]',
        'Oskar Nausch, originario de Wuppertal (Alemania) y establecido desde hace años en la República Dominicana, dirige la Tabacalera Don Esteban, una pequeña fábrica de Santiago de los Caballeros. El comerciante alemán cigarworld.de, que trabaja con él desde hace casi veinte años, presenta Capadura como su propia marca, liada a mano en esa fábrica y distribuida en Alemania desde junio de 2021 tras unos inicios en Suiza y Austria. Un portal de proveedores (eldiquetrading.com) sitúa sin embargo a Capadura entre las producciones de Don Esteban junto a Samana, Cibao y numerosas marcas privadas confeccionadas para terceros, sin precisar si Capadura tiene el mismo estatus de marca privada o es una creación propia de Nausch; la vinculación exacta —casa propia o marca de catálogo confiada por un distribuidor— no queda, pues, zanjada de forma definitiva por las fuentes encontradas.

El catálogo a la venta cuenta con diez variantes según cigarworld.de, cuya tripa combina tabacos brasileños; el distribuidor lo presenta como equilibrado, para aficionados a los puros medium. Ninguna línea individual está documentada por nombre, capa o fuerza en las fuentes consultadas; esta ficha se atiene, por tanto, a esta descripción de conjunto.',
        '[{"name":"Capadura","color":"#8B5A2B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Tripa brasileña, disponible en diez vitolas, según cigarworld.de."}]',
        'Oskar Nausch, gebürtig aus Wuppertal (Deutschland) und seit Jahren in der Dominikanischen Republik ansässig, leitet die Tabacalera Don Esteban, eine kleine Fabrik in Santiago de los Caballeros. Der deutsche Zigarrenhändler cigarworld.de, der seit fast zwanzig Jahren mit ihm zusammenarbeitet, stellt Capadura als dessen eigene Marke vor, von Hand in dieser Fabrik gerollt und seit Juni 2021 in Deutschland vertrieben, nach Anfängen in der Schweiz und in Österreich. Ein Lieferantenportal (eldiquetrading.com) ordnet Capadura jedoch unter den Produktionen von Don Esteban ein, neben Samana, Cibao und zahlreichen für Dritte gefertigten Eigenmarken, ohne anzugeben, ob Capadura denselben Status einer Eigenmarke hat oder eine eigene Schöpfung Nauschs ist; die genaue Zuordnung — eigenständiges Haus oder von einem Vertrieb anvertraute Katalogmarke — wird von den gefundenen Quellen also nicht endgültig geklärt.

Das erhältliche Sortiment umfasst laut cigarworld.de zehn Varianten, deren Einlage brasilianische Tabake verbindet; der Vertrieb stellt es als ausgewogen dar, für Liebhaber mittelkräftiger Zigarren. Keine einzelne Linie ist in den herangezogenen Quellen nach Namen, Deckblatt oder Stärke belegt; dieser Eintrag hält sich daher an diese Gesamtbeschreibung.',
        '[{"name":"Capadura","color":"#8B5A2B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Brasilianische Einlage, in zehn Formaten erhältlich, laut cigarworld.de."}]',
        '奥斯卡·瑙施（Oskar Nausch）出生于德国伍珀塔尔，多年来定居多米尼加共和国，主持着圣地亚哥-德洛斯卡瓦耶罗斯的一家小型工厂 Tabacalera Don Esteban。与他合作近二十年的德国雪茄经销商 cigarworld.de 将 Capadura 介绍为瑙施本人的品牌，在该厂手工卷制，自2021年6月起在德国销售，此前先在瑞士与奥地利起步。然而一家供应商门户网站（eldiquetrading.com）将 Capadura 列入 Don Esteban 旗下产品之列，与 Samana、Cibao 以及众多为第三方定制的私牌产品并列，并未说明 Capadura 是否属于同类私牌，还是瑙施本人的独立创作；因此，其确切归属——究竟是独立品牌，还是经销商托付的目录品牌——在查到的资料中并无定论。

据 cigarworld.de 介绍，在售产品线共有十个品种，其茄芯混有巴西烟叶；经销商将其形容为口感均衡，适合中等浓度雪茄的爱好者。查阅过的资料中没有任何单一系列按名称、茄衣或浓淡被记录在案；因此本词条仅以此整体描述为准。',
        '[{"name":"Capadura","color":"#8B5A2B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"巴西茄芯，共十种规格，据 cigarworld.de 介绍。"}]',
        'أوسكار ناوش، القادم أصلًا من فوبرتال (ألمانيا) والمقيم منذ سنوات في جمهورية الدومينيكان، يدير Tabacalera Don Esteban، وهو مصنع صغير في سانتياغو دي لوس كاباييروس. ويقدِّم تاجر السيجار الألماني cigarworld.de، الذي يتعامل معه منذ نحو عشرين عامًا، علامة Capadura بوصفها علامته الخاصة، تُلفّ باليد في هذا المصنع وتُوزَّع في ألمانيا منذ حزيران/يونيو 2021 بعد انطلاقة في سويسرا والنمسا. غير أنّ بوّابة موردين (eldiquetrading.com) تضع Capadura ضمن منتجات Don Esteban إلى جانب Samana وCibao وعلامات خاصة عديدة تُصنع لصالح أطراف أخرى، من دون أن توضّح ما إذا كانت Capadura تحمل الوضع نفسه لعلامة خاصة أم أنها إبداع خاص بناوش؛ ولذلك فإنّ الانتماء الدقيق — دار مستقلة أم علامة كتالوج عهد بها موزِّع — لا تحسمه المصادر التي عُثر عليها حسمًا نهائيًا.

يضمّ الكتالوج المعروض للبيع عشرة أصناف بحسب cigarworld.de، تجمع حشوتها تبوغًا برازيلية؛ ويقدّمه الموزِّع بوصفه متوازنًا، لمحبّي السيجار متوسط القوة. ولا يوثِّق أيّ من المصادر المُراجَعة أيّ خطّ فردي بالاسم أو الغلاف أو القوة؛ لذلك تكتفي هذه البطاقة بهذا الوصف الإجمالي.',
        '[{"name":"Capadura","color":"#8B5A2B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"حشوة برازيلية، بعشرة قياسات، بحسب cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Chateau Diadem ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Chateau Diadem',
        'dominican',
        '2020 ou 2022 (halfwheel) — Farah, Sahakian',
        'Usine propre — Chateau Diadem, Navarrete, zone franche PISANO (République dominicaine)',
        'halfwheel.com « Chateau Diadem Enters U.S. Market » (date non précisée : fondation en 2020 par les cousins suisses Thierry Farah et Emily Sahakian, usine à Navarrete) ; halfwheel.com « Chateau Diadem Launching Rebranded Certitude Line At PCA 2025 » (2025 : la ligne Conviction est rebaptisée Certitude pour le marché américain, lancée au salon PCA 2025 ; situe la fondation de la maison en 2022) ; halfwheel.com « Chateau Diadem Bringing Splendor Stateside Next Month » (2026 : la ligne Splendor, créée par Eladio Díaz, cape Corojo équatorienne et sous-cape mexicaine San Andrés, en vente en Europe depuis 2024, annoncée aux États-Unis) ; havanahouse.co.uk « Chateau Diadem Cigars » (date non précisée : cigares entièrement roulés à la main en République dominicaine) ; cigarjournal.com « Chateau Diadem''s Splendor » (date non précisée : détails sur la ligne Splendor) ; cigarjournal.com « Chateau Diadem Launches Two New Cigars » (date non précisée : lignes Alisio et Midnight Wonder, capes et force) ; chateaudiadem.com « Chateau Diadem » (site officiel, date non précisée : liste les lignes Alisio, Conviction, Midnight Wonder, Splendor, Monkey Business et Certitude USA, cigares dits roulés à la main en République dominicaine)',
        NULL,
        'Selon un premier article de halfwheel, Chateau Diadem est fondée en 2020 par les cousins suisses Thierry Farah et Emily Sahakian, installés en République dominicaine ; un article plus récent du même site, consacré au lancement de la ligne Certitude, situe plutôt la fondation en 2022, sans que les deux versions soient conciliées par les sources consultées. La maison possède sa propre fabrique à Navarrete, dans la zone franche industrielle PISANO au nord de Santiago (halfwheel), où ses cigares sont entièrement roulés à la main (havanahouse.co.uk).

Le catalogue compte plusieurs lignes : la Splendor, créée par le rouleur Eladio Díaz avec cape équatorienne Corojo, sous-cape mexicaine San Andrés et tripe dominicaine, en vente en Europe depuis 2024, et que halfwheel annonçait aux États-Unis pour le printemps 2026 ; l''Alisio, pensée plus légère et abordable, cape équatorienne Corojo et tripe dominicaine et nicaraguayenne ; et la Midnight Wonder, à cape Connecticut Broadleaf, mise au point en près de trois ans. La ligne Conviction a par ailleurs été rebaptisée Certitude pour le marché américain, lancée au salon PCA 2025 (halfwheel) ; le site de la maison mentionne aussi une ligne Monkey Business, sans détail de cape ni de force.',
        '[{"name":"Splendor","color":"#A0522D","force":null,"wrapper":"Corojo équatorien","vitolas":[],"story":"Créée par le rouleur Eladio Díaz, sous-cape mexicaine San Andrés, en vente en Europe depuis 2024, dit halfwheel."},{"name":"Alisio","color":"#A0522D","force":"Mild-Medium","wrapper":"Corojo équatorien","vitolas":[],"story":"Pensée comme un cigare plus léger et abordable, nommé d''après un vent dominicain."},{"name":"Midnight Wonder","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Assemblage mis au point en près de trois ans autour d''une cape Connecticut Broadleaf."}]',
        'According to an initial halfwheel article, Chateau Diadem was founded in 2020 by the Swiss cousins Thierry Farah and Emily Sahakian, settled in the Dominican Republic; a more recent article from the same site, devoted to the launch of the Certitude line, instead places the founding in 2022, with the two versions not reconciled by the sources consulted. The house owns its own factory at Navarrete, in the PISANO industrial free-trade zone north of Santiago (halfwheel), where its cigars are entirely hand-rolled (havanahouse.co.uk).

The range includes several lines: the Splendor, created by the roller Eladio Díaz with an Ecuadorian Corojo wrapper, a Mexican San Andrés binder and Dominican filler, on sale in Europe since 2024, and which halfwheel reported would reach the United States in the spring of 2026; the Alisio, conceived as lighter and more affordable, with an Ecuadorian Corojo wrapper and Dominican and Nicaraguan filler; and the Midnight Wonder, with a Connecticut Broadleaf wrapper, developed over close to three years. The Conviction line, moreover, was renamed Certitude for the American market and launched at the PCA 2025 trade show (halfwheel); the house''s website also mentions a Monkey Business line, with no detail given on wrapper or strength.',
        '[{"name":"Splendor","color":"#A0522D","force":null,"wrapper":"Ecuadorian Corojo","vitolas":[],"story":"Created by the roller Eladio Díaz, with a Mexican San Andrés binder, on sale in Europe since 2024, according to halfwheel."},{"name":"Alisio","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuadorian Corojo","vitolas":[],"story":"Conceived as a lighter, more affordable cigar, named after a Dominican wind."},{"name":"Midnight Wonder","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"A blend developed over close to three years around a Connecticut Broadleaf wrapper."}]',
        'Según un primer artículo de halfwheel, Chateau Diadem se funda en 2020 por los primos suizos Thierry Farah y Emily Sahakian, instalados en la República Dominicana; un artículo más reciente del mismo sitio, dedicado al lanzamiento de la línea Certitude, sitúa en cambio la fundación en 2022, sin que las fuentes consultadas concilien ambas versiones. La casa posee su propia fábrica en Navarrete, en la zona franca industrial PISANO al norte de Santiago (halfwheel), donde sus puros se lían enteramente a mano (havanahouse.co.uk).

El catálogo cuenta con varias líneas: la Splendor, creada por el torcedor Eladio Díaz con capa ecuatoriana Corojo, capote mexicano San Andrés y tripa dominicana, a la venta en Europa desde 2024, y que halfwheel anunciaba para Estados Unidos para la primavera de 2026; la Alisio, pensada como un puro más ligero y asequible, capa ecuatoriana Corojo y tripa dominicana y nicaragüense; y la Midnight Wonder, con capa Connecticut Broadleaf, desarrollada a lo largo de casi tres años. La línea Conviction, por lo demás, fue rebautizada como Certitude para el mercado estadounidense y lanzada en la feria PCA 2025 (halfwheel); el sitio de la casa menciona también una línea Monkey Business, sin detalle de capa ni de fuerza.',
        '[{"name":"Splendor","color":"#A0522D","force":null,"wrapper":"Corojo ecuatoriano","vitolas":[],"story":"Creada por el torcedor Eladio Díaz, con capote mexicano San Andrés, a la venta en Europa desde 2024, según halfwheel."},{"name":"Alisio","color":"#A0522D","force":"Mild-Medium","wrapper":"Corojo ecuatoriano","vitolas":[],"story":"Pensada como un puro más ligero y asequible, llamado así por un viento dominicano."},{"name":"Midnight Wonder","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Liga desarrollada a lo largo de casi tres años en torno a una capa Connecticut Broadleaf."}]',
        'Einem ersten Artikel von halfwheel zufolge wurde Chateau Diadem 2020 von den Schweizer Cousins Thierry Farah und Emily Sahakian gegründet, die sich in der Dominikanischen Republik niedergelassen hatten; ein neuerer Artikel derselben Seite, der Einführung der Linie Certitude gewidmet, verortet die Gründung dagegen 2022, ohne dass die herangezogenen Quellen beide Versionen in Einklang bringen. Das Haus besitzt seine eigene Fabrik in Navarrete, in der Industrie-Freihandelszone PISANO nördlich von Santiago (halfwheel), wo seine Zigarren vollständig von Hand gerollt werden (havanahouse.co.uk).

Das Sortiment umfasst mehrere Linien: die Splendor, geschaffen vom Torcedor Eladio Díaz mit einem ecuadorianischen Corojo-Deckblatt, einem mexikanischen San-Andrés-Umblatt und dominikanischer Einlage, seit 2024 in Europa im Verkauf und laut halfwheel für das Frühjahr 2026 in den Vereinigten Staaten angekündigt; die Alisio, als leichtere und günstigere Zigarre gedacht, mit ecuadorianischem Corojo-Deckblatt und dominikanischer sowie nicaraguanischer Einlage; und die Midnight Wonder mit Connecticut-Broadleaf-Deckblatt, über beinahe drei Jahre entwickelt. Die Linie Conviction wurde zudem für den amerikanischen Markt in Certitude umbenannt und auf der Messe PCA 2025 vorgestellt (halfwheel); die Website des Hauses erwähnt außerdem eine Linie Monkey Business, ohne Angaben zu Deckblatt oder Stärke.',
        '[{"name":"Splendor","color":"#A0522D","force":null,"wrapper":"Ecuadorianischer Corojo","vitolas":[],"story":"Geschaffen vom Torcedor Eladio Díaz, mit einem mexikanischen San-Andrés-Umblatt, seit 2024 in Europa im Verkauf, laut halfwheel."},{"name":"Alisio","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuadorianischer Corojo","vitolas":[],"story":"Als leichtere, günstigere Zigarre gedacht, benannt nach einem dominikanischen Wind."},{"name":"Midnight Wonder","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Eine Mischung, über beinahe drei Jahre rund um ein Connecticut-Broadleaf-Deckblatt entwickelt."}]',
        '据 halfwheel 早前一篇报道，Chateau Diadem 由定居多米尼加共和国的瑞士表亲蒂埃里·法拉赫（Thierry Farah）与艾米莉·萨哈基扬（Emily Sahakian）于2020年创立；同一网站较近的一篇报道，围绕 Certitude 系列的推出，则将创立时间定在2022年，所查阅的资料并未调和这两种说法。该品牌在圣地亚哥以北的 PISANO 工业自由贸易区纳瓦雷特拥有自己的工厂（halfwheel），旗下雪茄在此完全手工卷制（havanahouse.co.uk）。

产品线包括多个系列：Splendor 由卷制师埃拉迪奥·迪亚斯（Eladio Díaz）创制，采用厄瓜多尔 Corojo 茄衣、墨西哥圣安德烈斯茄套与多米尼加茄芯，自2024年起在欧洲销售，据 halfwheel 报道计划于2026年春季进入美国市场；Alisio 定位更轻淡、更平价，采用厄瓜多尔 Corojo 茄衣，配多米尼加与尼加拉瓜茄芯；Midnight Wonder 采用康涅狄格宽叶茄衣，配方历时近三年调制而成。此外，Conviction 系列已更名为 Certitude 以进入美国市场，并在2025年 PCA 展会上推出（halfwheel）；该品牌网站还提到一个 Monkey Business 系列，但未说明茄衣或浓淡。',
        '[{"name":"Splendor","color":"#A0522D","force":null,"wrapper":"厄瓜多尔 Corojo","vitolas":[],"story":"由卷制师埃拉迪奥·迪亚斯创制，配墨西哥圣安德烈斯茄套，自2024年起在欧洲销售，据 halfwheel 介绍。"},{"name":"Alisio","color":"#A0522D","force":"Mild-Medium","wrapper":"厄瓜多尔 Corojo","vitolas":[],"story":"定位为更轻淡、更平价的雪茄，得名于多米尼加的一种风。"},{"name":"Midnight Wonder","color":"#4A3728","force":"Full","wrapper":"康涅狄格宽叶","vitolas":[],"story":"围绕康涅狄格宽叶茄衣历时近三年调制而成的配方。"}]',
        'بحسب مقال أول لموقع halfwheel، تأسّست Chateau Diadem سنة 2020 على يد قريبين سويسريين هما تييري فرح وإميلي سهاكيان، المقيمين في جمهورية الدومينيكان؛ في حين يضع مقال أحدث من الموقع نفسه، خُصِّص لإطلاق خطّ Certitude، التأسيس سنة 2022 بدلًا من ذلك، من دون أن توفّق المصادر المُراجَعة بين الروايتين. وتملك الدار مصنعها الخاص في نافاريتي، ضمن المنطقة الحرة الصناعية PISANO شمال سانتياغو (halfwheel)، حيث تُلفّ سيجارها بالكامل يدويًا (havanahouse.co.uk).

يضمّ الكتالوج عدّة خطوط: Splendor، من إبداع اللافّ إلياديو دياث، بغلاف كوروخو إكوادوري ورباط سان أندريس مكسيكي وحشوة دومينيكية، معروض للبيع في أوروبا منذ 2024، وكانت halfwheel تُعلن عن وصوله إلى الولايات المتحدة في ربيع 2026؛ وAlisio، المصمَّم ليكون أخفّ وأقرب منالًا، بغلاف كوروخو إكوادوري وحشوة دومينيكية ونيكاراغوية؛ وMidnight Wonder، بغلاف كونيتيكت برودليف، جرى تطويره على مدى نحو ثلاث سنوات. كما أُعيدت تسمية خطّ Conviction إلى Certitude من أجل السوق الأمريكية، وأُطلق في معرض PCA 2025 (halfwheel)؛ ويذكر موقع الدار أيضًا خطًّا باسم Monkey Business، من دون تفاصيل عن الغلاف أو القوة.',
        '[{"name":"Splendor","color":"#A0522D","force":null,"wrapper":"كوروخو إكوادوري","vitolas":[],"story":"من إبداع اللافّ إلياديو دياث، برباط سان أندريس مكسيكي، معروض للبيع في أوروبا منذ 2024، بحسب halfwheel."},{"name":"Alisio","color":"#A0522D","force":"Mild-Medium","wrapper":"كوروخو إكوادوري","vitolas":[],"story":"صُمِّم ليكون سيجارًا أخفّ وأقرب منالًا، سُمّي على اسم ريح دومينيكية."},{"name":"Midnight Wonder","color":"#4A3728","force":"Full","wrapper":"كونيتيكت برودليف","vitolas":[],"story":"خلطة جرى تطويرها على مدى نحو ثلاث سنوات حول غلاف كونيتيكت برودليف."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Notorious ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Notorious',
        'dominican',
        '2025 — Conor McGregor, Rép. dominicaine',
        'Chez MJ Frias Cigars (fondée en 1991 par Miguel Frias), Tamboril, province de Santiago, République dominicaine',
        'halfwheel.com « PCA 2026: Notorious Cigars » (janvier 2026 : annonce de la présence de Notorious, marque de Conor McGregor faite chez MJ Frias Cigars à Santiago, au salon PCA26) ; cigarjournal.com « Notorious by Conor McGregor Cigars Make a Big Entrance at PCA 26 » (28 avril 2026 : trois lignes — blend d''origine medium, Crème de la Crème plus douce sous cape équatorienne claire et sous-cape brésilienne d''Arapiraca, Unapologetic plus corsée sous cape Broadleaf ; formats Toro, Double Robusto, Corona Gorda ; fabrication chez MJ Frias à Santiago ; expansion à plus de vingt pays en un peu plus d''un an) ; coronacigar.com « M J Frias » (non daté : MJ Frias Cigar Company, fondée à Santiago par Miguel Frias en 1991, relocalisée à Tamboril en 2002, cigares faits main à prix accessibles) ; cigardojo.com « Conor McGregor Launches Notorious Cigars » (mars 2025 : lancement de la marque ; cape Habano équatorienne 2000 Rosado Oscura vieillie environ quatre ans, sous-cape San Andrés mexicaine, tripe du Nicaragua et de République dominicaine) ; premiumcigars.org « PCA26 Returns to New Orleans April 17–20, 2026 » (confirme les dates du salon PCA26, du 17 au 20 avril 2026) ; cigar-coop.com « Notorious Cigars Introduces Unapologetic at PCA 2026 » (7 mai 2026 : Unapologetic, cape Connecticut Broadleaf, sous-cape Sumatra d''Équateur, tripe du Nicaragua, des États-Unis et de République dominicaine ; Corona Larga, Toro, Sublime, Sixty, boîtes de dix ; roulée chez MJ Frias) ; halfwheel.com « Conor McGregor''s Notorious Cigars Ships Unapologetic and Crème de la Crème » (2026 : les deux lignes livrées)',
        NULL,
        'Notorious est lancée en mars 2025, selon Cigar Dojo, par le combattant irlandais d''arts martiaux mixtes Conor McGregor. La marque se roule à la main chez MJ Frias Cigars, à Tamboril, dans la province de Santiago, en République dominicaine — une fabrique ouverte en 1991 à Santiago par Miguel Frias, relocalisée à Tamboril en 2002, qui roule à la main des cigares à prix accessibles, selon le détaillant Corona Cigar.

Le blend d''origine mêle des tabacs du Nicaragua, de République dominicaine et du Mexique, en Toro, Double Robusto et Corona Gorda ; des revendeurs lui donnent une cape équatorienne Habano 2000 Rosado Oscura vieillie environ quatre ans. La maison dit avoir gagné plus de vingt pays en un peu plus d''un an. Au salon PCA de La Nouvelle-Orléans, en avril 2026, elle présente deux blends nouveaux, livrés depuis selon halfwheel : Crème de la Crème, plus doux, sous cape équatorienne claire, sous-cape brésilienne d''Arapiraca et tripe du Nicaragua, de République dominicaine et de Colombie ; et Unapologetic, plus corsé, sous cape Connecticut Broadleaf américaine, sous-cape Sumatra d''Équateur et tripe du Nicaragua, des États-Unis et de République dominicaine, en quatre formats — Corona Larga, Toro, Sublime et Sixty.',
        '[{"name":"Notorious","color":"#8B5A2B","force":"Medium","wrapper":"Équateur Habano 2000","vitolas":[],"story":"Le blend d''origine : cape Habano 2000 Rosado Oscura vieillie environ quatre ans et sous-cape San Andrés, selon des revendeurs."},{"name":"Crème de la Crème","color":"#C9A96E","force":null,"wrapper":"Équateur, cape claire","vitolas":[],"story":"Sous-cape brésilienne d''Arapiraca, tripe du Nicaragua, de République dominicaine et de Colombie."},{"name":"Unapologetic","color":"#4A3728","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Sous-cape Sumatra d''Équateur, tripe du Nicaragua, des États-Unis et de République dominicaine ; Corona Larga, Toro, Sublime et Sixty, en boîtes de dix."}]',
        'Notorious was launched in March 2025, according to Cigar Dojo, by Irish mixed martial arts fighter Conor McGregor. The brand is hand-rolled at MJ Frias Cigars, in Tamboril, in the province of Santiago, in the Dominican Republic — a factory opened in 1991 in Santiago by Miguel Frias, relocated to Tamboril in 2002, which hand-rolls accessibly priced cigars, according to retailer Corona Cigar.

The original blend combines tobaccos from Nicaragua, the Dominican Republic and Mexico, in Toro, Double Robusto and Corona Gorda; retailers give it an Ecuadorian Habano 2000 Rosado Oscura wrapper aged around four years. The house says it has reached more than twenty countries in a little over a year. At the PCA trade show in New Orleans, in April 2026, it presented two new blends, shipped since then according to halfwheel: Crème de la Crème, milder, under a light Ecuadorian wrapper, a Brazilian Arapiraca binder and filler from Nicaragua, the Dominican Republic and Colombia; and Unapologetic, fuller-bodied, under an American Connecticut Broadleaf wrapper, an Ecuadorian Sumatra binder and filler from Nicaragua, the United States and the Dominican Republic, in four sizes — Corona Larga, Toro, Sublime and Sixty.',
        '[{"name":"Notorious","color":"#8B5A2B","force":"Medium","wrapper":"Ecuador Habano 2000","vitolas":[],"story":"The original blend: Habano 2000 Rosado Oscura wrapper aged around four years and a San Andrés binder, according to retailers."},{"name":"Crème de la Crème","color":"#C9A96E","force":null,"wrapper":"Ecuador, light wrapper","vitolas":[],"story":"Brazilian Arapiraca binder, filler from Nicaragua, the Dominican Republic and Colombia."},{"name":"Unapologetic","color":"#4A3728","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Ecuadorian Sumatra binder, filler from Nicaragua, the United States and the Dominican Republic; Corona Larga, Toro, Sublime and Sixty, in boxes of ten."}]',
        'Notorious se lanzó en marzo de 2025, según Cigar Dojo, de la mano del luchador irlandés de artes marciales mixtas Conor McGregor. La marca se elabora a mano en MJ Frias Cigars, en Tamboril, provincia de Santiago, República Dominicana — una fábrica abierta en 1991 en Santiago por Miguel Frias, trasladada a Tamboril en 2002, que elabora a mano puros a precios asequibles, según el minorista Corona Cigar.

La mezcla original combina tabacos de Nicaragua, República Dominicana y México, en Toro, Double Robusto y Corona Gorda; varios revendedores le atribuyen una capa ecuatoriana Habano 2000 Rosado Oscura envejecida unos cuatro años. La casa afirma haber llegado a más de veinte países en poco más de un año. En la feria PCA de Nueva Orleans, en abril de 2026, presentó dos mezclas nuevas, ya distribuidas según halfwheel: Crème de la Crème, más suave, con capa ecuatoriana clara, capote brasileño de Arapiraca y tripa de Nicaragua, República Dominicana y Colombia; y Unapologetic, más intenso, con capa Connecticut Broadleaf estadounidense, capote Sumatra de Ecuador y tripa de Nicaragua, Estados Unidos y República Dominicana, en cuatro vitolas — Corona Larga, Toro, Sublime y Sixty.',
        '[{"name":"Notorious","color":"#8B5A2B","force":"Medium","wrapper":"Ecuador Habano 2000","vitolas":[],"story":"La mezcla original: capa Habano 2000 Rosado Oscura envejecida unos cuatro años y capote San Andrés, según varios revendedores."},{"name":"Crème de la Crème","color":"#C9A96E","force":null,"wrapper":"Ecuador, capa clara","vitolas":[],"story":"Capote brasileño de Arapiraca, tripa de Nicaragua, República Dominicana y Colombia."},{"name":"Unapologetic","color":"#4A3728","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Capote Sumatra de Ecuador, tripa de Nicaragua, Estados Unidos y República Dominicana; Corona Larga, Toro, Sublime y Sixty, en cajas de diez."}]',
        'Notorious wurde im März 2025 laut Cigar Dojo vom irischen Mixed-Martial-Arts-Kämpfer Conor McGregor lanciert. Die Marke wird bei MJ Frias Cigars von Hand gerollt, in Tamboril, in der Provinz Santiago, Dominikanische Republik — eine Fabrik, die 1991 in Santiago von Miguel Frias eröffnet und 2002 nach Tamboril verlegt wurde und laut dem Händler Corona Cigar handgerollte Zigarren zu erschwinglichen Preisen herstellt.

Die ursprüngliche Mischung vereint Tabake aus Nicaragua, der Dominikanischen Republik und Mexiko, in den Formaten Toro, Double Robusto und Corona Gorda; Händler geben ihr ein ecuadorianisches Habano-2000-Rosado-Oscura-Deckblatt mit rund vier Jahren Reifung. Das Haus gibt an, in etwas mehr als einem Jahr mehr als zwanzig Länder erreicht zu haben. Auf der PCA-Messe in New Orleans stellte sie im April 2026 zwei neue Mischungen vor, seither laut halfwheel ausgeliefert: Crème de la Crème, milder, mit hellem ecuadorianischem Deckblatt, brasilianischem Arapiraca-Umblatt und Einlage aus Nicaragua, der Dominikanischen Republik und Kolumbien; sowie Unapologetic, kräftiger, mit amerikanischem Connecticut-Broadleaf-Deckblatt, ecuadorianischem Sumatra-Umblatt und Einlage aus Nicaragua, den Vereinigten Staaten und der Dominikanischen Republik, in vier Formaten — Corona Larga, Toro, Sublime und Sixty.',
        '[{"name":"Notorious","color":"#8B5A2B","force":"Medium","wrapper":"Ecuador Habano 2000","vitolas":[],"story":"Die ursprüngliche Mischung: Habano-2000-Rosado-Oscura-Deckblatt mit rund vier Jahren Reifung und San-Andrés-Umblatt, laut Händlern."},{"name":"Crème de la Crème","color":"#C9A96E","force":null,"wrapper":"Ecuador, helles Deckblatt","vitolas":[],"story":"Brasilianisches Arapiraca-Umblatt, Einlage aus Nicaragua, der Dominikanischen Republik und Kolumbien."},{"name":"Unapologetic","color":"#4A3728","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Ecuadorianisches Sumatra-Umblatt, Einlage aus Nicaragua, den Vereinigten Staaten und der Dominikanischen Republik; Corona Larga, Toro, Sublime und Sixty, in Kisten zu zehn Stück."}]',
        '据Cigar Dojo报道，Notorious于2025年3月由爱尔兰综合格斗选手康纳·麦格雷戈推出。该品牌在多米尼加共和国圣地亚哥省坦博里尔的MJ Frias Cigars手工卷制——据零售商Corona Cigar介绍，这家工厂由米格尔·弗里亚斯于1991年在圣地亚哥开设，2002年迁至坦博里尔，手工卷制价格亲民的雪茄。

最初的配方混合了尼加拉瓜、多米尼加共和国和墨西哥的烟叶，规格有Toro、Double Robusto和Corona Gorda；多家经销商称其茄衣为陈化约四年的厄瓜多尔Habano 2000 Rosado Oscura茄衣。该品牌称在一年多一点的时间里已进入二十多个国家。2026年4月，在新奥尔良举行的PCA展会上，该品牌推出两款新配方，据halfwheel报道现已发货：Crème de la Crème更为温和，采用浅色厄瓜多尔茄衣、巴西阿拉皮拉卡茄套，茄芯来自尼加拉瓜、多米尼加共和国和哥伦比亚；Unapologetic则更为浓郁，采用美国康涅狄格宽叶茄衣、厄瓜多尔苏门答腊茄套，茄芯来自尼加拉瓜、美国和多米尼加共和国，共有四种规格——Corona Larga、Toro、Sublime和Sixty。',
        '[{"name":"Notorious","color":"#8B5A2B","force":"Medium","wrapper":"厄瓜多尔Habano 2000","vitolas":[],"story":"最初的配方：茄衣为陈化约四年的Habano 2000 Rosado Oscura，茄套为圣安德烈斯，据多家经销商介绍。"},{"name":"Crème de la Crème","color":"#C9A96E","force":null,"wrapper":"厄瓜多尔，浅色茄衣","vitolas":[],"story":"巴西阿拉皮拉卡茄套，茄芯来自尼加拉瓜、多米尼加共和国和哥伦比亚。"},{"name":"Unapologetic","color":"#4A3728","force":null,"wrapper":"康涅狄格宽叶","vitolas":[],"story":"厄瓜多尔苏门答腊茄套，茄芯来自尼加拉瓜、美国和多米尼加共和国；规格有Corona Larga、Toro、Sublime和Sixty，十支装。"}]',
        'أُطلقت علامة Notorious في مارس 2025، وفق Cigar Dojo، على يد المقاتل الإيرلندي في الفنون القتالية المختلطة كونور ماكغريغور. وتُلفّ العلامة يدويًا في MJ Frias Cigars، في تامبوريل بمقاطعة سانتياغو، جمهورية الدومينيكان — وهو مصنع افتتحه ميغيل فرياس سنة 1991 في سانتياغو، ثم نُقل إلى تامبوريل سنة 2002، وينتج وفق تاجر التجزئة Corona Cigar سيجارًا مُلفوفًا يدويًا بأسعار معقولة.

أمّا الخلطة الأصلية فتمزج تبغًا من نيكاراغوا وجمهورية الدومينيكان والمكسيك، بمقاسات Toro وDouble Robusto وCorona Gorda؛ وينسب إليها بعض الموزّعين غلاف Habano 2000 Rosado Oscura إكوادوري معتّق نحو أربع سنوات. وتقول الدار إنها بلغت أكثر من عشرين بلدًا في ما يزيد قليلًا على سنة. وفي معرض PCA بنيو أورلينز، في أبريل 2026، قدّمت خلطتين جديدتين، تُشحنان منذ ذلك الحين وفق halfwheel: Crème de la Crème، وهي ألطف، بغلاف إكوادوري فاتح وورقة رابطة برازيلية من أرابيراكا وحشوة من نيكاراغوا وجمهورية الدومينيكان وكولومبيا؛ وUnapologetic، وهي أشدّ قوةً، بغلاف كونيتيكت برودليف أمريكي وورقة رابطة سومطرة إكوادورية وحشوة من نيكاراغوا والولايات المتحدة وجمهورية الدومينيكان، بأربعة مقاسات — Corona Larga وToro وSublime وSixty.',
        '[{"name":"Notorious","color":"#8B5A2B","force":"Medium","wrapper":"إكوادور Habano 2000","vitolas":[],"story":"الخلطة الأصلية: غلاف Habano 2000 Rosado Oscura معتّق نحو أربع سنوات وورقة رابطة سان أندريس، وفق بعض الموزّعين."},{"name":"Crème de la Crème","color":"#C9A96E","force":null,"wrapper":"إكوادور، غلاف فاتح","vitolas":[],"story":"ورقة رابطة برازيلية من أرابيراكا، وحشوة من نيكاراغوا وجمهورية الدومينيكان وكولومبيا."},{"name":"Unapologetic","color":"#4A3728","force":null,"wrapper":"كونيتيكت برودليف","vitolas":[],"story":"ورقة رابطة سومطرة إكوادورية، وحشوة من نيكاراغوا والولايات المتحدة وجمهورية الدومينيكان؛ بمقاسات Corona Larga وToro وSublime وSixty، بعلب من عشر قطع."}]')
