-- ── Simon Beltre ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Simon Beltre',
        'dominican',
        '2017 — famille Beltré, Azua',
        'Usine propre — exploitation familiale Beltré, Azua, République dominicaine',
        'cigarsmokerclub.com « Simon Beltre Cigars » (non daté : famille Beltré, 4e génération de planteurs d''Azua ; Simón Beltré initié au tabac en 1976 à cinq ans par son grand-père Andrés « Don Titi » Beltré et son père Alcibiades Beltré ; marque SB née en 2017) ; toropuro.com « Simon Beltre » (en anglais, page de collection ; non daté : importateur britannique ; gamme CSZ, Andullo et un assortiment Momentos ; CSZ dite plus corsée et structurée, Andullo dite pleine, élaborée avec des yaguas de palmier royal affinées plusieurs années) ; jpb.ro « Simon Beltre » (en anglais ; non daté : revendeur roumain ; détail du blend CSZ Swiss Chocolate — tripe Semilla 2020, San Vicente, Negrito et SVM, sous-cape Olor Dominicano, cape Habano équatorienne H-2000)',
        NULL,
        'Simon Beltre est une marque dominicaine portée par la famille Beltré, cultivateurs de tabac à Azua depuis plusieurs générations. Selon plusieurs revendeurs européens, le fondateur, Simón Beltré, est initié au tabac dès 1976, à cinq ans, par son grand-père Andrés Beltré, dit « Don Titi », et par son père Alcibiades Beltré, sur les terres familiales. La marque SB naît de cette histoire en 2017.

Les cigares sont faits à la main dans l''exploitation familiale, à Azua ; aucune source consultée ne nomme de fabrique distincte ni ne précise la ville exacte au-delà de la province. Le catalogue propre compte notamment la CSZ, dite « Swiss Chocolate » par un revendeur roumain, sous cape Habano équatorienne H-2000, sous-cape Olor Dominicano et tripe de Semilla 2020, San Vicente, Negrito et SVM ; et l''Andullo, affinée dans des yaguas de palmier royal selon la tradition dominicaine du même nom, dit un importateur britannique. Les deux lignes restent au catalogue de plusieurs revendeurs européens.',
        '[{"name":"CSZ","color":"#8B5A2B","force":"Full","wrapper":"Équateur Habano H-2000","vitolas":[],"story":"Sous-cape Olor Dominicano, tripe Semilla 2020, San Vicente, Negrito et SVM, dite « Swiss Chocolate » par un revendeur roumain ; plus corsée et structurée, selon un importateur britannique."},{"name":"Andullo","color":"#4A2C1A","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Affinée dans des yaguas de palmier royal selon la tradition dominicaine de l''andullo, dit un importateur britannique."}]',
        'Simon Beltre is a Dominican brand carried by the Beltré family, tobacco growers in Azua for several generations. According to several European retailers, the founder, Simón Beltré, was introduced to tobacco as early as 1976, at the age of five, by his grandfather Andrés Beltré, known as Don Titi, and by his father Alcibiades Beltré, on the family land. The SB brand was born from this story in 2017.

The cigars are hand-made on the family holding, in Azua; no source consulted names a separate factory or specifies the exact town beyond the province. The house''s own catalogue notably includes the CSZ, called Swiss Chocolate by a Romanian retailer, under an Ecuadorian Habano H-2000 wrapper, an Olor Dominicano binder and a filler of Semilla 2020, San Vicente, Negrito and SVM; and the Andullo, cured in royal palm yagua according to the Dominican andullo tradition, says a British importer. Both lines remain in the catalogue of several European retailers.',
        '[{"name":"CSZ","color":"#8B5A2B","force":"Full","wrapper":"Ecuador Habano H-2000","vitolas":[],"story":"Olor Dominicano binder, Semilla 2020, San Vicente, Negrito and SVM filler, called Swiss Chocolate by a Romanian retailer; fuller-bodied and more structured, according to a British importer."},{"name":"Andullo","color":"#4A2C1A","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Cured in royal palm yagua according to the Dominican andullo tradition, says a British importer."}]',
        'Simon Beltre es una marca dominicana impulsada por la familia Beltré, cultivadores de tabaco en Azua desde hace varias generaciones. Según varios revendedores europeos, el fundador, Simón Beltré, se inició en el tabaco ya en 1976, a los cinco años, de la mano de su abuelo Andrés Beltré, apodado Don Titi, y de su padre Alcibiades Beltré, en las tierras familiares. La marca SB nace de esta historia en 2017.

Los puros se elaboran a mano en la explotación familiar, en Azua; ninguna fuente consultada nombra una fábrica aparte ni precisa la ciudad exacta más allá de la provincia. El catálogo propio incluye sobre todo el CSZ, llamado Swiss Chocolate por un revendedor rumano, con capa Habano ecuatoriana H-2000, capote Olor Dominicano y tripa de Semilla 2020, San Vicente, Negrito y SVM; y el Andullo, curado en yaguas de palma real según la tradición dominicana del andullo, según un importador británico. Ambas líneas siguen en el catálogo de varios revendedores europeos.',
        '[{"name":"CSZ","color":"#8B5A2B","force":"Full","wrapper":"Ecuador Habano H-2000","vitolas":[],"story":"Capote Olor Dominicano, tripa de Semilla 2020, San Vicente, Negrito y SVM, llamado Swiss Chocolate por un revendedor rumano; más fuerte y estructurado, según un importador británico."},{"name":"Andullo","color":"#4A2C1A","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Curada en yaguas de palma real según la tradición dominicana del andullo, según un importador británico."}]',
        'Simon Beltre ist eine dominikanische Marke der Familie Beltré, die seit mehreren Generationen in Azua Tabak anbaut. Mehreren europäischen Händlern zufolge wurde der Gründer, Simón Beltré, bereits 1976, im Alter von fünf Jahren, von seinem Großvater Andrés Beltré, genannt Don Titi, und von seinem Vater Alcibiades Beltré auf dem Familienland an den Tabak herangeführt. Die Marke SB entstand 2017 aus dieser Geschichte.

Die Zigarren werden auf dem Familienbetrieb in Azua von Hand gefertigt; keine befragte Quelle nennt eine eigene Fabrik oder die genaue Stadt jenseits der Provinz. Der eigene Katalog umfasst vor allem die CSZ, von einem rumänischen Händler Swiss Chocolate genannt, mit ecuadorianischem Habano-H-2000-Deckblatt, Olor-Dominicano-Umblatt und einer Einlage aus Semilla 2020, San Vicente, Negrito und SVM; sowie die Andullo, laut einem britischen Importeur in Yagua-Blättern der Königspalme gereift, nach der gleichnamigen dominikanischen Andullo-Tradition. Beide Linien stehen weiterhin im Katalog mehrerer europäischer Händler.',
        '[{"name":"CSZ","color":"#8B5A2B","force":"Full","wrapper":"Ecuador Habano H-2000","vitolas":[],"story":"Umblatt Olor Dominicano, Einlage aus Semilla 2020, San Vicente, Negrito und SVM, von einem rumänischen Händler Swiss Chocolate genannt; kräftiger und strukturierter, laut einem britischen Importeur."},{"name":"Andullo","color":"#4A2C1A","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Laut einem britischen Importeur in Yagua-Blättern der Königspalme gereift, nach der dominikanischen Andullo-Tradition."}]',
        'Simon Beltre是多米尼加品牌，由贝尔特雷家族经营，该家族在阿苏阿种植烟草已有数代。据多家欧洲经销商介绍，创始人西蒙·贝尔特雷早在1976年、五岁时便由祖父安德烈斯·贝尔特雷（人称唐·蒂蒂）和父亲阿尔西比亚德斯·贝尔特雷在家族的土地上引入烟草世界。SB品牌由此于2017年诞生。

雪茄在阿苏阿的家族庄园手工制作；查阅的资料均未提及另有独立工厂，也未在省份之外说明确切城镇。自有目录主要包括CSZ——一位罗马尼亚经销商称之为Swiss Chocolate，茄衣为厄瓜多尔Habano H-2000，茄套为Olor Dominicano，茄芯为Semilla 2020、圣比森特、Negrito和SVM；以及Andullo——据一位英国进口商介绍，按同名多米尼加传统以王棕叶鞘卷裹陈化。这两条产品线仍列于多家欧洲经销商的目录中。',
        '[{"name":"CSZ","color":"#8B5A2B","force":"Full","wrapper":"厄瓜多尔Habano H-2000","vitolas":[],"story":"茄套为Olor Dominicano，茄芯为Semilla 2020、圣比森特、Negrito和SVM，一位罗马尼亚经销商称之为Swiss Chocolate；据一位英国进口商介绍，力度更强、结构感更明显。"},{"name":"Andullo","color":"#4A2C1A","force":"Full","wrapper":"未公开","vitolas":[],"story":"据一位英国进口商介绍，按多米尼加的andullo传统，以王棕叶鞘卷裹陈化。"}]',
        'Simon Beltre علامة دومينيكية تحملها عائلة بيلتري، التي تزرع التبغ في أزوا منذ أجيال عدة. ووفق عدد من الموزّعين الأوروبيين، بدأ المؤسّس سيمون بيلتري صلته بالتبغ منذ 1976، وهو في الخامسة من عمره، على يد جدّه أندريس بيلتري، الملقّب دون تيتي، ووالده ألكيبياديس بيلتري، في أراضي العائلة. وُلدت علامة SB من هذه القصة سنة 2017.

تُصنع السيجارات يدويًا في المزرعة العائلية، في أزوا؛ ولا يذكر أيّ مصدر رجعنا إليه مصنعًا منفصلًا ولا يحدّد المدينة بدقة خارج نطاق المقاطعة. ويضمّ الكتالوج الخاص بشكل خاص CSZ، التي يسمّيها موزّع روماني Swiss Chocolate، بغلاف Habano H-2000 إكوادوري وورقة رابطة Olor Dominicano وحشوة من Semilla 2020 وسان بيسنتي وNegrito وSVM؛ وandullo، المعتّقة في أغلفة سعف النخيل الملكي وفق التقليد الدومينيكي الذي يحمل الاسم نفسه، بحسب مستورد بريطاني. ولا يزال الخطّان مُدرجين في كتالوجات عدة موزّعين أوروبيين.',
        '[{"name":"CSZ","color":"#8B5A2B","force":"Full","wrapper":"إكوادور Habano H-2000","vitolas":[],"story":"ورقة رابطة Olor Dominicano، وحشوة من Semilla 2020 وسان بيسنتي وNegrito وSVM، يسمّيها موزّع روماني Swiss Chocolate؛ أشدّ قوةً وتماسكًا في البنية، وفق مستورد بريطاني."},{"name":"Andullo","color":"#4A2C1A","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"معتّقة في أغلفة سعف النخيل الملكي وفق تقليد andullo الدومينيكي، بحسب مستورد بريطاني."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Vallejuelo ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Vallejuelo',
        'dominican',
        '2008 — Maurice Koks (Pays-Bas), marché suisse',
        'Chez Intercigar S.A., zone franche La Palma, Tamboril (Rép. dominicaine) — bâtiment incendié en septembre 2022',
        'thecigarauthority.com « Vallejuelo Gran Toro Cigar Review » (non daté : création en 2008 pour le marché suisse à la demande d''un distributeur ; roulée à la main chez Intercigar S.A., Zona Franca La Palma, Tamboril ; propriétaire Maurice Antonius Koks) ; holts.com « Vallejuelo » (en anglais ; non daté : cape Habano équatorienne, tripe dominicaine et nicaraguayenne, sous-cape nicaraguayenne ; formats Robusto et Robusto Gordo, boîtes de vingt) ; intercigar.com « Vallejuelo » (en anglais ; non daté : deux lignes — Classic Vallejuelo, cape Habano rosado, lancée en 2008, boîtes de vingt ; Vallejuelo Medio Tiempo, cape San Andrés mexicaine et feuille medio tiempo, boîtes de dix-huit ; marque d''Intercigar S.A., parc industriel de Tamboril) ; absolutecigars.com « Vallejuelo » (en anglais ; non daté : nom signifiant « petite vallée » ; formats Gran Toro, Gordo, Robusto Gordo, Robusto ; incendie de l''usine Intercigar en septembre 2022, avec la Tabacalera William Ventura voisine ; stock réduit depuis) ; intercigar.com « Our Cigars » (en anglais ; consulté en septembre 2026 : Vallejuelo toujours listée parmi les marques d''Intercigar)',
        NULL,
        'Vallejuelo est une marque créée en 2008, à la demande d''un distributeur suisse et pour ce marché, dit le fabricant. Son nom signifie « petite vallée ». Elle appartient à Maurice Antonius Koks, originaire des Pays-Bas, qui en est aussi le blender selon le fabricant, et se roule à la main chez Intercigar S.A., dans la zone franche La Palma, à Tamboril, province de Santiago.

La maison décline deux blends. Le Classic Vallejuelo, lancé en 2008, associe une cape Habano équatorienne rosado à une tripe dominicaine et nicaraguayenne, sous une sous-cape nicaraguayenne ; il se vend en plusieurs formats — Robusto, Robusto Gordo, Gran Toro, Gordo — en boîtes de vingt. Le Vallejuelo Medio Tiempo, plus corsé dit le fabricant, emploie de la feuille medio tiempo sous une cape mexicaine San Andrés, en boîtes de dix-huit. En septembre 2022, un incendie a détruit à Tamboril le bâtiment qu''Intercigar partageait avec la Tabacalera William Ventura. Le site d''Intercigar, consulté en septembre 2026, liste toujours les deux Vallejuelo parmi ses marques ; où elles se roulent depuis l''incendie, aucune source consultée ne le dit.',
        '[{"name":"Classic Vallejuelo","color":"#A0522D","force":"Medium-Full","wrapper":"Habano équatorienne rosado","vitolas":[],"story":"Le blend d''origine, lancé en 2008 pour le marché suisse, dit le fabricant."},{"name":"Vallejuelo Medio Tiempo","color":"#6B4226","force":"Full","wrapper":"Mexique San Andrés","vitolas":[],"story":"Plus corsé que le Classic, avec de la feuille medio tiempo, dit le fabricant ; boîtes de dix-huit."}]',
        'Vallejuelo is a brand created in 2008, at the request of a Swiss distributor and for that market, says the manufacturer. Its name means small valley. It belongs to Maurice Antonius Koks, from the Netherlands, who is also its blender according to the manufacturer, and is hand-rolled at Intercigar S.A., in the La Palma free zone, in Tamboril, Santiago province.

The house offers two blends. The Classic Vallejuelo, launched in 2008, pairs an Ecuadorian Habano rosado wrapper with a Dominican and Nicaraguan filler, under a Nicaraguan binder; it is sold in several sizes — Robusto, Robusto Gordo, Gran Toro, Gordo — in boxes of twenty. The Vallejuelo Medio Tiempo, fuller-bodied according to the manufacturer, uses medio tiempo leaf under a Mexican San Andrés wrapper, in boxes of eighteen. In September 2022, a fire destroyed the building in Tamboril that Intercigar shared with Tabacalera William Ventura. Intercigar''s website, checked in September 2026, still lists both Vallejuelos among its brands; where they have been rolled since the fire, no source consulted says.',
        '[{"name":"Classic Vallejuelo","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuadorian Habano rosado","vitolas":[],"story":"The original blend, launched in 2008 for the Swiss market, says the manufacturer."},{"name":"Vallejuelo Medio Tiempo","color":"#6B4226","force":"Full","wrapper":"Mexican San Andrés","vitolas":[],"story":"Fuller-bodied than the Classic, with medio tiempo leaf, says the manufacturer; boxes of eighteen."}]',
        'Vallejuelo es una marca creada en 2008, a petición de un distribuidor suizo y para ese mercado, dice el fabricante. Su nombre significa pequeño valle. Pertenece a Maurice Antonius Koks, originario de los Países Bajos, quien es también su ligador según el fabricante, y se elabora a mano en Intercigar S.A., en la zona franca La Palma, en Tamboril, provincia de Santiago.

La casa ofrece dos mezclas. El Classic Vallejuelo, lanzado en 2008, combina una capa Habano ecuatoriana rosado con una tripa dominicana y nicaragüense, bajo un capote nicaragüense; se vende en varios formatos — Robusto, Robusto Gordo, Gran Toro, Gordo — en cajas de veinte. El Vallejuelo Medio Tiempo, más fuerte según el fabricante, emplea hoja medio tiempo bajo una capa mexicana San Andrés, en cajas de dieciocho. En septiembre de 2022, un incendio destruyó en Tamboril el edificio que Intercigar compartía con la Tabacalera William Ventura. El sitio web de Intercigar, consultado en septiembre de 2026, sigue enumerando ambos Vallejuelo entre sus marcas; dónde se elaboran desde el incendio, ninguna fuente consultada lo dice.',
        '[{"name":"Classic Vallejuelo","color":"#A0522D","force":"Medium-Full","wrapper":"Habano ecuatoriana rosado","vitolas":[],"story":"La mezcla original, lanzada en 2008 para el mercado suizo, según el fabricante."},{"name":"Vallejuelo Medio Tiempo","color":"#6B4226","force":"Full","wrapper":"México San Andrés","vitolas":[],"story":"Más fuerte que el Classic, con hoja medio tiempo, según el fabricante; cajas de dieciocho."}]',
        'Vallejuelo ist eine 2008 auf Wunsch eines Schweizer Vertriebspartners und für diesen Markt geschaffene Marke, so der Hersteller. Ihr Name bedeutet kleines Tal. Sie gehört dem aus den Niederlanden stammenden Maurice Antonius Koks, der laut Hersteller auch ihr Blender ist, und wird bei Intercigar S.A. in der Freizone La Palma in Tamboril, Provinz Santiago, von Hand gerollt.

Das Haus führt zwei Mischungen. Der Classic Vallejuelo, 2008 eingeführt, verbindet ein ecuadorianisches Habano-Rosado-Deckblatt mit einer dominikanisch-nicaraguanischen Einlage unter einem nicaraguanischen Umblatt; er wird in mehreren Formaten verkauft — Robusto, Robusto Gordo, Gran Toro, Gordo — in Kisten zu zwanzig Stück. Der Vallejuelo Medio Tiempo, laut Hersteller kräftiger, verwendet Medio-Tiempo-Blätter unter einem mexikanischen San-Andrés-Deckblatt, in Kisten zu achtzehn Stück. Im September 2022 zerstörte ein Brand in Tamboril das Gebäude, das sich Intercigar mit der Tabacalera William Ventura teilte. Die im September 2026 aufgerufene Website von Intercigar führt weiterhin beide Vallejuelo-Linien unter ihren Marken; wo seit dem Brand gerollt wird, sagt keine befragte Quelle.',
        '[{"name":"Classic Vallejuelo","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuadorianisches Habano rosado","vitolas":[],"story":"Die ursprüngliche Mischung, 2008 für den Schweizer Markt eingeführt, so der Hersteller."},{"name":"Vallejuelo Medio Tiempo","color":"#6B4226","force":"Full","wrapper":"Mexikanisches San Andrés","vitolas":[],"story":"Kräftiger als der Classic, mit Medio-Tiempo-Blatt, so der Hersteller; Kisten zu achtzehn Stück."}]',
        'Vallejuelo是一个创立于2008年的品牌，据厂方介绍，是应一家瑞士经销商的要求、为该市场而创立的。其名意为小山谷。品牌归荷兰人莫里斯·安东尼乌斯·科克斯所有，据厂方介绍他本人也是调配师，产品在圣地亚哥省坦博里尔拉帕尔马自由区的Intercigar S.A.手工卷制。

厂方共有两款配方。Classic Vallejuelo于2008年推出，将厄瓜多尔Habano rosado茄衣与多米尼加和尼加拉瓜茄芯搭配，外覆尼加拉瓜茄套；有多种规格——Robusto、Robusto Gordo、Gran Toro、Gordo——二十支装。Vallejuelo Medio Tiempo据厂方介绍力度更强，采用medio tiempo烟叶，茄衣为墨西哥圣安德烈斯，十八支装。2022年9月，一场大火烧毁了Intercigar在坦博里尔与Tabacalera William Ventura共用的厂房。截至2026年9月查阅，Intercigar网站仍将两款Vallejuelo列在其品牌之中；火灾之后产品在何处卷制，查阅的资料均未说明。',
        '[{"name":"Classic Vallejuelo","color":"#A0522D","force":"Medium-Full","wrapper":"厄瓜多尔Habano rosado","vitolas":[],"story":"最初的配方，据厂方介绍于2008年为瑞士市场推出。"},{"name":"Vallejuelo Medio Tiempo","color":"#6B4226","force":"Full","wrapper":"墨西哥圣安德烈斯","vitolas":[],"story":"比Classic力度更强，采用medio tiempo烟叶，据厂方介绍；十八支装。"}]',
        'علامة Vallejuelo أُنشئت سنة 2008، بطلب من موزّع سويسري ولذلك السوق، وفق الصانع. ويعني اسمها الوادي الصغير. وتعود ملكيتها إلى موريس أنطونيوس كوكس، القادم من هولندا، وهو أيضًا خبير مزجها وفق الصانع، وتُلفّ يدويًا في Intercigar S.A.، بالمنطقة الحرة لا بالما، في تامبوريل بمقاطعة سانتياغو.

تقدّم الدار خلطتين. فـClassic Vallejuelo، الذي أُطلق سنة 2008، يجمع بين غلاف Habano rosado إكوادوري وحشوة دومينيكية ونيكاراغوية، تحت ورقة رابطة نيكاراغوية؛ ويُباع بعدّة مقاسات — Robusto وRobusto Gordo وGran Toro وGordo — بعلب من عشرين قطعة. أمّا Vallejuelo Medio Tiempo، وهو حسب الصانع أشدّ قوةً، فيستخدم ورق medio tiempo تحت غلاف سان أندريس مكسيكي، بعلب من ثماني عشرة قطعة. وفي سبتمبر 2022، دمّر حريق في تامبوريل المبنى الذي كانت Intercigar تتقاسمه مع Tabacalera William Ventura. ولا يزال موقع Intercigar، الذي جرت زيارته في سبتمبر 2026، يُدرج كلا اسمي Vallejuelo ضمن علاماته؛ أمّا أين تُلفّ منذ الحريق فلا يذكر ذلك أيّ مصدر رجعنا إليه.',
        '[{"name":"Classic Vallejuelo","color":"#A0522D","force":"Medium-Full","wrapper":"Habano rosado إكوادوري","vitolas":[],"story":"الخلطة الأصلية، أُطلقت سنة 2008 من أجل السوق السويسرية، وفق الصانع."},{"name":"Vallejuelo Medio Tiempo","color":"#6B4226","force":"Full","wrapper":"سان أندريس مكسيكي","vitolas":[],"story":"أقوى من Classic، بورق medio tiempo، وفق الصانع؛ بعلب من ثماني عشرة قطعة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Stauffenberg ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Stauffenberg',
        'honduras',
        '2025 — Maik Neubauer, Allemagne',
        'Chez La Pequeña Vega, Danlí, Honduras',
        'cigarjournal.com « Stauffenberg Cigars positioniert Angebot auch im Alpenraum » (en allemand ; non daté : marque de Maik Neubauer, roulée d''abord à La Pequeña Vega, Danlí ; arrivée en Allemagne à l''été 2025 puis extension Autriche/Suisse) ; cigarjournal.com « Two New Cigars from Stauffenberg » (non daté : confirme Maik Neubauer et La Pequeña Vega, Danlí ; Édition 2 Robusto annoncée après l''Édition 1 Pyramides, tirage de 3000) ; cigarjournal.com « 3 Editions from Stauffenberg » (non daté : Édition 1 Pyramides 6x52 disponible depuis mai 2025, corps léger à moyen ; Édition 2 Robusto 5x54 ; Édition 3 Toro 6x54 corps complet, roulée à Danlí, sortie annoncée pour novembre 2025 ; une quatrième édition, alors nommée « Project White », annoncée pour 2026) ; hacico.de « Stauffenberg Edition 2 Robusto » (en allemand ; non daté : fiche produit — 5x54, cape, sous-cape et tripe Criollo du Honduras en puro, roulé à la main, fabricant La Pequeña Vega, en stock depuis le 8 septembre 2025) ; vdg-cigars.com « Stauffenberg''s Cigars is Expanding Their Portfolio » (non daté : évoque une quatrième édition à cape candela)',
        NULL,
        'Stauffenberg est une marque allemande portée par Maik Neubauer, qui a voulu créer son propre cigare hondurien. Elle se roule à la main à La Pequeña Vega, manufacture familiale de Danlí, au Honduras. La première édition arrive en Allemagne en mai 2025, en tirage limité à 3 000 exemplaires, avant l''extension du réseau de vente à l''Autriche et à la Suisse.

Le catalogue s''écrit par éditions numérotées plutôt que par lignes nommées. L''Edition 1 est un Pyramides en puro Criollo 98 hondurien : cape, sous-cape et tripe du même tabac. L''Edition 2, un Robusto également puro Criollo hondurien, se vend depuis septembre 2025. L''Edition 3, un Toro corsé roulé à Danlí, voit sa sortie annoncée pour novembre 2025. Une Edition 4, à cape candela, était annoncée pour 2026. Son nom rend hommage, selon la maison, à Claus Schenk Graf von Stauffenberg et aux résistants allemands au nazisme.',
        '[{"name":"Edition 1 (Pyramides)","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras Criollo 98","vitolas":[],"story":"Puro hondurien — cape, sous-cape et tripe du même tabac —, tirage de 3 000 cigares, arrivé en Allemagne en mai 2025."},{"name":"Edition 2 (Robusto)","color":"#A0522D","force":null,"wrapper":"Honduras Criollo","vitolas":[],"story":"Puro hondurien au format 5x54, en stock chez un caviste allemand depuis septembre 2025."},{"name":"Edition 3 (Toro)","color":"#6B4226","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Roulée à Danlí, sortie annoncée pour novembre 2025."}]',
        'Stauffenberg is a German brand carried by Maik Neubauer, who wanted to create his own Honduran cigar. It is hand-rolled at La Pequeña Vega, a family factory in Danlí, Honduras. The first edition reached Germany in May 2025, in a limited run of 3,000, before the sales network extended to Austria and Switzerland.

The catalogue is written as numbered editions rather than named lines. The Edition 1 is a Pyramides in Honduran puro Criollo 98: wrapper, binder and filler from the same tobacco. The Edition 2, also a Honduran puro Criollo Robusto, has been on sale since September 2025. The Edition 3, a full-bodied Toro rolled in Danlí, has its release announced for November 2025. An Edition 4, with a candela wrapper, was announced for 2026. Its name pays tribute, according to the house, to Claus Schenk Graf von Stauffenberg and to the German resistance to Nazism.',
        '[{"name":"Edition 1 (Pyramides)","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras Criollo 98","vitolas":[],"story":"Honduran puro — wrapper, binder and filler from the same tobacco —, a run of 3,000 cigars, which reached Germany in May 2025."},{"name":"Edition 2 (Robusto)","color":"#A0522D","force":null,"wrapper":"Honduras Criollo","vitolas":[],"story":"Honduran puro in 5x54 format, in stock at a German tobacconist since September 2025."},{"name":"Edition 3 (Toro)","color":"#6B4226","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Rolled in Danlí, release announced for November 2025."}]',
        'Stauffenberg es una marca alemana impulsada por Maik Neubauer, que quiso crear su propio puro hondureño. Se elabora a mano en La Pequeña Vega, manufactura familiar de Danlí, Honduras. La primera edición llega a Alemania en mayo de 2025, en una tirada limitada a 3000 unidades, antes de que la red de venta se extendiera a Austria y Suiza.

El catálogo se organiza por ediciones numeradas más que por líneas con nombre. La Edition 1 es un Pyramides puro Criollo 98 hondureño: capa, capote y tripa del mismo tabaco. La Edition 2, también un Robusto puro Criollo hondureño, se vende desde septiembre de 2025. La Edition 3, un Toro fuerte liado en Danlí, tiene su salida anunciada para noviembre de 2025. Una Edition 4, con capa candela, estaba anunciada para 2026. Su nombre rinde homenaje, según la casa, a Claus Schenk Graf von Stauffenberg y a la resistencia alemana al nazismo.',
        '[{"name":"Edition 1 (Pyramides)","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras Criollo 98","vitolas":[],"story":"Puro hondureño — capa, capote y tripa del mismo tabaco —, tirada de 3000 puros, llegado a Alemania en mayo de 2025."},{"name":"Edition 2 (Robusto)","color":"#A0522D","force":null,"wrapper":"Honduras Criollo","vitolas":[],"story":"Puro hondureño en formato 5x54, en existencia en una tienda especializada alemana desde septiembre de 2025."},{"name":"Edition 3 (Toro)","color":"#6B4226","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Liado en Danlí, salida anunciada para noviembre de 2025."}]',
        'Stauffenberg ist eine deutsche Marke von Maik Neubauer, der seine eigene honduranische Zigarre schaffen wollte. Sie wird von Hand bei La Pequeña Vega gerollt, einer Familienmanufaktur in Danlí, Honduras. Die erste Edition kam im Mai 2025 nach Deutschland, in einer auf 3.000 Stück limitierten Auflage, bevor sich das Vertriebsnetz auf Österreich und die Schweiz ausweitete.

Der Katalog gliedert sich in nummerierte Editionen statt benannte Linien. Die Edition 1 ist eine Pyramides als honduranischer Criollo-98-Puro: Deckblatt, Umblatt und Einlage aus demselben Tabak. Die Edition 2, ebenfalls ein honduranischer Criollo-Puro als Robusto, wird seit September 2025 verkauft. Die Edition 3, eine kräftige, in Danlí gerollte Toro, hat ihren für November 2025 angekündigten Marktstart. Eine Edition 4 mit Candela-Deckblatt war für 2026 angekündigt. Ihr Name ehrt laut dem Haus Claus Schenk Graf von Stauffenberg und den deutschen Widerstand gegen den Nationalsozialismus.',
        '[{"name":"Edition 1 (Pyramides)","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras Criollo 98","vitolas":[],"story":"Honduranischer Puro — Deckblatt, Umblatt und Einlage aus demselben Tabak —, Auflage von 3.000 Zigarren, im Mai 2025 in Deutschland eingetroffen."},{"name":"Edition 2 (Robusto)","color":"#A0522D","force":null,"wrapper":"Honduras Criollo","vitolas":[],"story":"Honduranischer Puro im Format 5x54, seit September 2025 bei einem deutschen Zigarrenhändler vorrätig."},{"name":"Edition 3 (Toro)","color":"#6B4226","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"In Danlí gerollt, Marktstart für November 2025 angekündigt."}]',
        'Stauffenberg是迈克·诺伊鲍尔创立的德国品牌，他希望打造属于自己的洪都拉斯雪茄。产品在洪都拉斯丹利的家族工厂La Pequeña Vega手工卷制。首款系列于2025年5月进入德国市场，限量3000支，随后销售网络扩展到奥地利和瑞士。

该品牌的产品目录以编号系列而非命名产品线呈现。Edition 1是一款Pyramides，纯洪都拉斯Criollo 98配方：茄衣、茄套和茄芯均为同一种烟叶。Edition 2同样是纯洪都拉斯Criollo配方的Robusto，自2025年9月起发售。Edition 3是一款在丹利卷制的浓郁Toro，发布日期定于2025年11月。Edition 4采用candela茄衣，原定于2026年推出。据品牌介绍，其名称是为纪念克劳斯·申克·冯·施陶芬贝格伯爵及德国反纳粹抵抗运动人士。',
        '[{"name":"Edition 1 (Pyramides)","color":"#A0522D","force":"Mild-Medium","wrapper":"洪都拉斯Criollo 98","vitolas":[],"story":"纯洪都拉斯配方——茄衣、茄套和茄芯均为同一种烟叶——限量3000支，2025年5月进入德国市场。"},{"name":"Edition 2 (Robusto)","color":"#A0522D","force":null,"wrapper":"洪都拉斯Criollo","vitolas":[],"story":"纯洪都拉斯配方，规格5x54，自2025年9月起在一家德国雪茄专卖店有售。"},{"name":"Edition 3 (Toro)","color":"#6B4226","force":"Full","wrapper":"未公开","vitolas":[],"story":"在丹利卷制，发布日期定于2025年11月。"}]',
        'Stauffenberg علامة ألمانية يحملها مايك نويباور، الذي أراد ابتكار سيجاره الهندوراسي الخاص. تُلفّ يدويًا في La Pequeña Vega، وهو مصنع عائلي في دانلي بهندوراس. وصلت الطبعة الأولى إلى ألمانيا في مايو 2025، بإصدار محدود من 3000 قطعة، قبل أن تتوسّع شبكة البيع لتشمل النمسا وسويسرا.

يُكتب الكتالوج بطبعات مرقّمة بدل خطوط تحمل أسماء. فالطبعة Edition 1 هي Pyramides من puro Criollo 98 هندوراسي خالص: غلاف وورقة رابطة وحشوة من التبغ نفسه. والطبعة Edition 2، وهي أيضًا Robusto من puro Criollo هندوراسي، تُباع منذ سبتمبر 2025. والطبعة Edition 3، وهي Toro قوية تُلفّ في دانلي، أُعلن عن طرحها في نوفمبر 2025. وكانت هناك طبعة Edition 4، بغلاف candela، أُعلن عنها من أجل 2026. ووفق الدار، يكرّم اسمها كلاوس شينك غراف فون شتاوفنبرغ والمقاومين الألمان للنازية.',
        '[{"name":"Edition 1 (Pyramides)","color":"#A0522D","force":"Mild-Medium","wrapper":"Criollo 98 هندوراسي","vitolas":[],"story":"puro هندوراسي خالص — غلاف وورقة رابطة وحشوة من التبغ نفسه — بإصدار من 3000 سيجار، وصل إلى ألمانيا في مايو 2025."},{"name":"Edition 2 (Robusto)","color":"#A0522D","force":null,"wrapper":"Criollo هندوراسي","vitolas":[],"story":"puro هندوراسي بمقاس 5x54، متوفّر لدى متجر تبغ ألماني منذ سبتمبر 2025."},{"name":"Edition 3 (Toro)","color":"#6B4226","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"تُلفّ في دانلي، وأُعلن عن طرحها في نوفمبر 2025."}]')
