-- ── El Gaucho ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('El Gaucho',
        'indonesia',
        '2022 — Besuki Raya Cigars, Jember',
        'Usine propre — PT Besuki Raya Cigar, région de Jember, Java oriental (Indonésie)',
        'elgauchocigars.co.id « El Gaucho Cigars » (consulté 2026-09-24 : deux lignes — Premium et Fantastico —, cape équatorienne, sous-cape brésilienne d''Arapiraca, tripe dominicaine, et aussi indonésienne pour la Fantastico, boîtier pressé de 54 de cepo en trois formats — Square, Toro, Chiquitos —, roulage dit entièrement à la main par la marque) ; besukirayacigar.co.id « Besuki Raya Cigars » (date non précisée : PT Besuki Raya Cigar fondée en 2020, filiale du groupe Mangli Djaya Raya qui travaille le tabac de Jember depuis 2009 ; El Gaucho, lancé en 2022, premier produit premium de la maison après Rojo Blanco en 2020, My Lockdown et Lauk Daun en 2021) ; tobaccoasia.com « The Renaissance of Indonesia''s Premium Cigar Industry » (consulté 2026-09-24 : Besuki Raya Cigars, filiale indépendante depuis 2020 du groupe Mangli Djaya Raya présidé par Christian A. Njoto Njoo, dans la région de Besuki et Jember à l''est de Java ; Monsoon Cigar s''associe à Besuki Raya pour rouler la marque Mata Hari) ; intertabac.de « PT Besuki Raya Cigar » (date non précisée : profil d''exposant listant quatre lignes, El Gaucho de 2022 citée comme produit phare, sans préciser main ou machine)',
        NULL,
        'El Gaucho est la marque premium phare de Besuki Raya Cigars (PT Besuki Raya Cigar), installée à Jember, dans l''est de Java. BRC, filiale indépendante depuis 2020 du groupe indonésien Mangli Djaya Raya (MDR, présidé par Christian A. Njoto Njoo), cultive le tabac de la région de Besuki et Jember depuis 2009, avant de se lancer dans le cigare premium, disent la presse professionnelle Tobacco Asia et le profil d''exposant du salon Intertabac. El Gaucho, lancé en 2022 après, dit la marque, trois années de stockage du tabac, en est le premier produit haut de gamme, précédé chez BRC par Rojo Blanco (2020) puis My Lockdown et Lauk Daun (2021). El Gaucho dit rouler ses cigares entièrement à la main ; aucune des deux sources indépendantes ne le confirme explicitement, ni ne mentionne de machine.

Le catalogue compte deux lignes, toutes deux en boîtier pressé de 54 de cepo et déclinées en trois formats — Square, Toro, Chiquitos. La Premium associe une cape équatorienne à une sous-cape brésilienne d''Arapiraca et une tripe dominicaine, sur des notes de chocolat, cannelle et café que la marque dit moyennement à pleinement corsées. La Fantastico, sous cape équatorienne de variété habano, mêle à la même sous-cape brésilienne une tripe dominicaine et indonésienne, pour un corps moyen aux notes de beurre et d''agrumes. À la même fabrique, Besuki Raya roule aussi, en association avec Monsoon Cigar, la marque Mata Hari.',
        '[{"name":"El Gaucho Premium","color":"#A0522D","force":"Medium-Full","wrapper":"Équateur","vitolas":[],"story":"Sous-cape brésilienne d''Arapiraca et tripe dominicaine, sur des notes de chocolat, cannelle et café, dit la marque."},{"name":"El Gaucho Fantastico","color":"#8B5A2B","force":"Medium","wrapper":"Équateur Habano","vitolas":[],"story":"Même sous-cape brésilienne, tripe dominicaine et indonésienne, pour un corps moyen aux notes de beurre et d''agrumes, dit la marque."}]',
        'El Gaucho is the flagship premium brand of Besuki Raya Cigars (PT Besuki Raya Cigar), based in Jember, in eastern Java. BRC, an independent subsidiary since 2020 of the Indonesian group Mangli Djaya Raya (MDR, chaired by Christian A. Njoto Njoo), has grown tobacco in the Besuki and Jember region since 2009, before moving into premium cigars, say trade press Tobacco Asia and the exhibitor profile of the Intertabac trade show. El Gaucho, launched in 2022 after, the brand says, three years of tobacco storage, is its first high-end product, preceded at BRC by Rojo Blanco (2020) and then My Lockdown and Lauk Daun (2021). El Gaucho says its cigars are rolled entirely by hand; neither of the two independent sources confirms this explicitly, nor mentions any machine.

The catalogue holds two lines, both in a pressed box of 54 ring gauge and offered in three sizes — Square, Toro, Chiquitos. The Premium pairs an Ecuadorian wrapper with a Brazilian Arapiraca binder and a Dominican filler, on notes of chocolate, cinnamon and coffee that the brand describes as medium to full-bodied. The Fantastico, under an Ecuadorian habano-variety wrapper, combines the same Brazilian binder with a Dominican and Indonesian filler, for a medium body with notes of butter and citrus. At the same factory, Besuki Raya, in partnership with Monsoon Cigar, also rolls the Mata Hari brand.',
        '[{"name":"El Gaucho Premium","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuador","vitolas":[],"story":"Brazilian Arapiraca binder and Dominican filler, on notes of chocolate, cinnamon and coffee, says the brand."},{"name":"El Gaucho Fantastico","color":"#8B5A2B","force":"Medium","wrapper":"Ecuador Habano","vitolas":[],"story":"Same Brazilian binder, Dominican and Indonesian filler, for a medium body with notes of butter and citrus, says the brand."}]',
        'El Gaucho es la marca premium insignia de Besuki Raya Cigars (PT Besuki Raya Cigar), instalada en Jember, en el este de Java. BRC, filial independiente desde 2020 del grupo indonesio Mangli Djaya Raya (MDR, presidido por Christian A. Njoto Njoo), cultiva tabaco en la región de Besuki y Jember desde 2009, antes de lanzarse al puro premium, según la prensa especializada Tobacco Asia y el perfil de expositor de la feria Intertabac. El Gaucho, lanzado en 2022 tras, dice la marca, tres años de almacenamiento del tabaco, es su primer producto de gama alta, precedido en BRC por Rojo Blanco (2020) y luego My Lockdown y Lauk Daun (2021). El Gaucho afirma liar sus puros enteramente a mano; ninguna de las dos fuentes independientes lo confirma de forma explícita, ni menciona máquina alguna.

El catálogo cuenta con dos líneas, ambas en caja prensada de 54 de cepo y disponibles en tres formatos — Square, Toro, Chiquitos. La Premium combina una capa ecuatoriana con un capote brasileño de Arapiraca y una tripa dominicana, con notas de chocolate, canela y café que la marca califica de medio a pleno cuerpo. La Fantastico, con capa ecuatoriana de variedad habano, combina el mismo capote brasileño con una tripa dominicana e indonesia, para un cuerpo medio con notas de mantequilla y cítricos. En la misma fábrica, Besuki Raya también lía, en asociación con Monsoon Cigar, la marca Mata Hari.',
        '[{"name":"El Gaucho Premium","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuador","vitolas":[],"story":"Capote brasileño de Arapiraca y tripa dominicana, con notas de chocolate, canela y café, según la marca."},{"name":"El Gaucho Fantastico","color":"#8B5A2B","force":"Medium","wrapper":"Ecuador Habano","vitolas":[],"story":"El mismo capote brasileño, tripa dominicana e indonesia, para un cuerpo medio con notas de mantequilla y cítricos, según la marca."}]',
        'El Gaucho ist die führende Premiummarke von Besuki Raya Cigars (PT Besuki Raya Cigar) mit Sitz in Jember, im Osten Javas. BRC, seit 2020 eine unabhängige Tochtergesellschaft der indonesischen Gruppe Mangli Djaya Raya (MDR, unter dem Vorsitz von Christian A. Njoto Njoo), baut seit 2009 Tabak in der Region Besuki und Jember an, bevor sie sich der Premiumzigarre zuwandte, so die Fachpresse Tobacco Asia und das Ausstellerprofil der Messe Intertabac. El Gaucho, 2022 eingeführt nach, laut Marke, drei Jahren Tabaklagerung, ist ihr erstes hochwertiges Produkt, dem bei BRC Rojo Blanco (2020) und dann My Lockdown und Lauk Daun (2021) vorausgingen. El Gaucho gibt an, seine Zigarren vollständig von Hand zu rollen; keine der beiden unabhängigen Quellen bestätigt dies ausdrücklich oder erwähnt eine Maschine.

Der Katalog umfasst zwei Linien, beide in einer gepressten Kiste mit 54er Ringmaß und in drei Formaten erhältlich — Square, Toro, Chiquitos. Die Premium verbindet ein ecuadorianisches Deckblatt mit einem brasilianischen Arapiraca-Umblatt und einer dominikanischen Einlage, mit Noten von Schokolade, Zimt und Kaffee, die die Marke als mittel- bis vollmundig bezeichnet. Die Fantastico, unter einem ecuadorianischen Deckblatt der Sorte Habano, verbindet dasselbe brasilianische Umblatt mit einer dominikanischen und indonesischen Einlage, für einen mittleren Körper mit Noten von Butter und Zitrus. In derselben Fabrik rollt Besuki Raya, in Zusammenarbeit mit Monsoon Cigar, auch die Marke Mata Hari.',
        '[{"name":"El Gaucho Premium","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuador","vitolas":[],"story":"Brasilianisches Arapiraca-Umblatt und dominikanische Einlage, mit Noten von Schokolade, Zimt und Kaffee, so die Marke."},{"name":"El Gaucho Fantastico","color":"#8B5A2B","force":"Medium","wrapper":"Ecuador Habano","vitolas":[],"story":"Dasselbe brasilianische Umblatt, dominikanische und indonesische Einlage, für einen mittleren Körper mit Noten von Butter und Zitrus, so die Marke."}]',
        'El Gaucho是Besuki Raya Cigars（PT Besuki Raya Cigar）的旗舰优质品牌，总部位于东爪哇的杰姆贝尔。BRC自2020年起成为印尼集团Mangli Djaya Raya（MDR，董事长为克里斯蒂安·A·尼约托·尼奥）旗下的独立子公司，自2009年起在贝苏基和杰姆贝尔地区种植烟草，此后才进入优质雪茄领域——行业媒体Tobacco Asia和Intertabac展会的参展商简介都是如此介绍的。El Gaucho据品牌介绍在烟叶陈放三年后于2022年推出，是其首款高端产品，此前BRC已有Rojo Blanco（2020年）及随后的My Lockdown和Lauk Daun（2021年）。El Gaucho称其雪茄完全手工卷制；两份独立资料均未明确证实这一点，也都没有提到机器。

产品目录共有两条产品线，均采用54环径的压制盒装，有三种规格——Square、Toro、Chiquitos。Premium将厄瓜多尔茄衣与巴西阿拉皮拉卡茄套、多米尼加茄芯搭配，带有巧克力、肉桂和咖啡的风味，品牌称其力度中等偏浓郁。Fantastico采用habano品种的厄瓜多尔茄衣，将同一款巴西茄套与多米尼加和印尼茄芯搭配，呈现中等力度，带有黄油和柑橘风味。在同一家工厂，Besuki Raya还与Monsoon Cigar合作卷制Mata Hari品牌。',
        '[{"name":"El Gaucho Premium","color":"#A0522D","force":"Medium-Full","wrapper":"厄瓜多尔","vitolas":[],"story":"巴西阿拉皮拉卡茄套与多米尼加茄芯，带有巧克力、肉桂和咖啡的风味，据品牌介绍。"},{"name":"El Gaucho Fantastico","color":"#8B5A2B","force":"Medium","wrapper":"厄瓜多尔habano","vitolas":[],"story":"同一款巴西茄套，多米尼加与印尼茄芯，呈现中等力度，带有黄油与柑橘风味，据品牌介绍。"}]',
        'El Gaucho هي العلامة الفاخرة الرائدة لشركة Besuki Raya Cigars (PT Besuki Raya Cigar)، الكائنة في جمبر، شرق جاوة. وتزرع BRC، وهي شركة تابعة مستقلة منذ 2020 لمجموعة Mangli Djaya Raya الإندونيسية (MDR، ويرأسها كريستيان أ. نيوتو نيو)، التبغَ في منطقة بيسوكي وجمبر منذ 2009، قبل أن تتّجه إلى السيجار الفاخر، وفق الصحافة المهنية Tobacco Asia وملف العارض في معرض Intertabac. وEl Gaucho، الذي أُطلق سنة 2022 بعد، وفق العلامة، ثلاث سنوات من تخزين التبغ، هو أوّل منتجاتها الراقية، وسبقته لدى BRC علامات Rojo Blanco (2020) ثم My Lockdown وLauk Daun (2021). وتقول El Gaucho إنّ سيجارها مُلفوف يدويًا بالكامل؛ ولا يؤكّد أيّ من المصدرين المستقلّين ذلك صراحةً، ولا يذكر أيّهما آلة.

يضمّ الكتالوج خطّين، كلاهما في علبة مضغوطة بقياس 54 حلقة وبثلاثة مقاسات — Square وToro وChiquitos. ويجمع خطّ Premium بين غلاف إكوادوري وورقة رابطة برازيلية من أرابيراكا وحشوة دومينيكية، بنكهات الشوكولاتة والقرفة والقهوة التي تصفها العلامة بأنّها متوسطة إلى ممتلئة القوة. أمّا Fantastico، بغلاف إكوادوري من صنف habano، فتجمع الورقة الرابطة البرازيلية نفسها مع حشوة دومينيكية وإندونيسية، بقوام متوسط ونكهات الزبدة والحمضيات. وفي المصنع نفسه، تُلفّ Besuki Raya أيضًا، بالشراكة مع Monsoon Cigar، علامة Mata Hari.',
        '[{"name":"El Gaucho Premium","color":"#A0522D","force":"Medium-Full","wrapper":"إكوادور","vitolas":[],"story":"ورقة رابطة برازيلية من أرابيراكا وحشوة دومينيكية، بنكهات الشوكولاتة والقرفة والقهوة، وفق العلامة."},{"name":"El Gaucho Fantastico","color":"#8B5A2B","force":"Medium","wrapper":"إكوادور habano","vitolas":[],"story":"الورقة الرابطة البرازيلية نفسها، وحشوة دومينيكية وإندونيسية، بقوام متوسط ونكهات الزبدة والحمضيات، وفق العلامة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Alfambra ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Alfambra',
        'nicaragua',
        '2015 — Alejandro Mata, Estelí',
        'Usine propre — Tabacalera Alfambra (atelier ouvert en 2007 par Alejandro Mata), Estelí (Nicaragua)',
        'cigarjournal.com « The Sun Rises For Everyone » (11 janvier 2023 : Alejandro Mata, entrepreneur de Málaga, ex-distributeur du rhum Havana Club ; rencontre d''Alejandro Robaina au Festival del Habano 2005 ; atelier ouvert à Estelí en 2007 avec deux couples de rouleurs, sur un tabac de Remedios dit La Flor de San Luis ; marque Alfambra lancée en 2015, nom médiéval de l''Alhambra ; premier cigare medium-filler à bague orange, 30 000 par an ; El Brujito, longfiller lancé trois ans plus tard, 840 000 cigares vendus selon Mata ; deux propriétés à Pueblo Nuevo, plus de cinquante hectares de terres au Nicaragua ; environ 6 000 cigares par jour, vendus dans douze pays européens) ; cigarjournal.com « New: Alejandro Mata » (consulté 2026-09-24 : nouvelle ligne Alejandro Mata dévoilée à Intertabac 2026, cape colorado en cinq formats, maduro en trois, force medium à full, vente internationale prévue en mars 2027, coffret limité Colección 1964 de 180 pièces) ; cigarsmokerclub.com « Alfambra Boutique Gran Toro: A Nicaraguan Cigar That Captivates With Every Draw » (consulté 2026-09-23 : ligne Alfambra Boutique et son Gran Toro) ; paginasamarillas.com.ni « Tabacalera Alfambra S.A. » (en espagnol ; date non précisée : société Tabacalera Alfambra à Estelí)',
        NULL,
        'Alfambra est la marque d''Alejandro Mata, entrepreneur espagnol de Málaga, alors distributeur du rhum Havana Club. Sa passion pour le cigare le mène au Festival del Habano en 2005, où il rencontre le planteur cubain Alejandro Robaina. Mata ouvre en 2007 un petit atelier à Estelí, où deux couples de rouleurs travaillent un tabac de Remedios, à Cuba, dit La Flor de San Luis, avant de lancer en 2015 la marque Alfambra — un nom que la presse rattache à l''Alhambra de Grenade —, avec un premier cigare medium-filler à bague orange, produit à 30 000 exemplaires par an. La fabrique, Tabacalera Alfambra, figure à Estelí dans l''annuaire nicaraguayen Páginas Amarillas. Ses propres terres, dont deux propriétés à Pueblo Nuevo, couvrent plus de cinquante hectares au Nicaragua, et la production est dite proche de 6 000 cigares par jour, vendus dans douze pays européens.

El Brujito, un longfiller lancé trois ans après les débuts, s''est vendu à 840 000 exemplaires, dit Alejandro Mata. Une ligne Boutique, dont un Gran Toro, complète le catalogue. Présentée à Intertabac 2026 et attendue sur le marché international en mars 2027, une nouvelle ligne baptisée Alejandro Mata rend hommage au fondateur : cape colorado en cinq formats, cape maduro en trois.',
        '[{"name":"El Brujito","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Longfiller lancé trois ans après les débuts de la marque ; 840 000 cigares vendus, dit Alejandro Mata."},{"name":"Alfambra Boutique","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dont un Gran Toro."},{"name":"Alejandro Mata Colorado","color":"#A0522D","force":"Medium-Full","wrapper":"Colorado","vitolas":[],"story":"Cinq formats, de l''Amanecer à l''Alba, dévoilés à Intertabac 2026 en hommage au fondateur."},{"name":"Alejandro Mata Maduro","color":"#4A3728","force":"Medium-Full","wrapper":"Maduro","vitolas":[],"story":"Trois formats, du Legado au Linaje, attendus sur le marché international en mars 2027."}]',
        'Alfambra is the brand of Alejandro Mata, a Spanish entrepreneur from Málaga, at the time a distributor of Havana Club rum. His passion for cigars took him to the Festival del Habano in 2005, where he met Cuban grower Alejandro Robaina. In 2007, Mata opened a small factory in Estelí, where two couples of rollers worked a tobacco from Remedios, in Cuba, called La Flor de San Luis, before launching the Alfambra brand in 2015 — a name the press links to the Alhambra of Granada —, with a first medium-filler cigar with an orange band, made at 30,000 a year. The factory, Tabacalera Alfambra, is listed in Estelí in the Nicaraguan directory Páginas Amarillas. Its own land, including two estates in Pueblo Nuevo, covers more than fifty hectares in Nicaragua, and output is said to be close to 6,000 cigars a day, sold in twelve European countries.

El Brujito, a longfiller launched three years after the brand''s beginnings, has sold 840,000 units, says Alejandro Mata. A Boutique line, including a Gran Toro, completes the catalogue. Presented at Intertabac 2026 and expected on the international market in March 2027, a new line named Alejandro Mata pays tribute to the founder: colorado wrapper in five sizes, maduro wrapper in three.',
        '[{"name":"El Brujito","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Longfiller launched three years after the brand''s beginnings; 840,000 cigars sold, says Alejandro Mata."},{"name":"Alfambra Boutique","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Line in the catalogue, including a Gran Toro."},{"name":"Alejandro Mata Colorado","color":"#A0522D","force":"Medium-Full","wrapper":"Colorado","vitolas":[],"story":"Five sizes, from the Amanecer to the Alba, unveiled at Intertabac 2026 in tribute to the founder."},{"name":"Alejandro Mata Maduro","color":"#4A3728","force":"Medium-Full","wrapper":"Maduro","vitolas":[],"story":"Three sizes, from the Legado to the Linaje, expected on the international market in March 2027."}]',
        'Alfambra es la marca de Alejandro Mata, empresario español de Málaga, entonces distribuidor del ron Havana Club. Su pasión por el puro lo lleva al Festival del Habano en 2005, donde conoce al agricultor cubano Alejandro Robaina. En 2007, Mata abre una pequeña fábrica en Estelí, donde dos parejas de torcedores trabajan un tabaco de Remedios, en Cuba, llamado La Flor de San Luis, antes de lanzar en 2015 la marca Alfambra — nombre que la prensa vincula con la Alhambra de Granada —, con un primer puro medium-filler de vitola naranja, producido a razón de 30 000 unidades al año. La fábrica, Tabacalera Alfambra, figura en Estelí en el directorio nicaragüense Páginas Amarillas. Sus propias tierras, entre ellas dos fincas en Pueblo Nuevo, superan las cincuenta hectáreas en Nicaragua, y la producción se sitúa, según se dice, cerca de los 6000 puros al día, vendidos en doce países europeos.

El Brujito, un longfiller lanzado tres años después de los inicios, se ha vendido en 840 000 unidades, dice Alejandro Mata. Una línea Boutique, con un Gran Toro, completa el catálogo. Presentada en Intertabac 2026 y esperada en el mercado internacional en marzo de 2027, una nueva línea llamada Alejandro Mata rinde homenaje al fundador: capa colorado en cinco formatos, capa maduro en tres.',
        '[{"name":"El Brujito","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Longfiller lanzado tres años después de los inicios de la marca; 840 000 puros vendidos, dice Alejandro Mata."},{"name":"Alfambra Boutique","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, con un Gran Toro."},{"name":"Alejandro Mata Colorado","color":"#A0522D","force":"Medium-Full","wrapper":"Colorado","vitolas":[],"story":"Cinco formatos, del Amanecer al Alba, presentados en Intertabac 2026 en homenaje al fundador."},{"name":"Alejandro Mata Maduro","color":"#4A3728","force":"Medium-Full","wrapper":"Maduro","vitolas":[],"story":"Tres formatos, del Legado al Linaje, esperados en el mercado internacional en marzo de 2027."}]',
        'Alfambra ist die Marke von Alejandro Mata, einem spanischen Unternehmer aus Málaga, der damals den Rum Havana Club vertrieb. Seine Leidenschaft für Zigarren führte ihn 2005 zum Festival del Habano, wo er den kubanischen Pflanzer Alejandro Robaina traf. 2007 eröffnete Mata eine kleine Fabrik in Estelí, in der zwei Roller-Paare einen Tabak aus Remedios, Kuba, namens La Flor de San Luis verarbeiteten, bevor er 2015 die Marke Alfambra lancierte — ein Name, den die Presse mit der Alhambra von Granada in Verbindung bringt —, mit einer ersten Medium-Filler-Zigarre mit orangefarbener Bauchbinde, hergestellt in einer Auflage von 30.000 Stück pro Jahr. Die Fabrik, Tabacalera Alfambra, ist in Estelí im nicaraguanischen Branchenverzeichnis Páginas Amarillas gelistet. Die eigenen Ländereien, darunter zwei Anwesen in Pueblo Nuevo, umfassen mehr als fünfzig Hektar in Nicaragua, und die Produktion liegt Berichten zufolge bei nahezu 6.000 Zigarren pro Tag, verkauft in zwölf europäischen Ländern.

El Brujito, ein drei Jahre nach der Gründung eingeführter Longfiller, hat sich 840.000 Mal verkauft, sagt Alejandro Mata. Eine Boutique-Linie, darunter ein Gran Toro, vervollständigt den Katalog. Eine auf der Intertabac 2026 vorgestellte und für März 2027 auf dem internationalen Markt erwartete neue Linie namens Alejandro Mata ehrt den Gründer: Colorado-Deckblatt in fünf Formaten, Maduro-Deckblatt in drei.',
        '[{"name":"El Brujito","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Longfiller, drei Jahre nach der Gründung der Marke eingeführt; 840.000 verkaufte Zigarren, sagt Alejandro Mata."},{"name":"Alfambra Boutique","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Katalog, darunter ein Gran Toro."},{"name":"Alejandro Mata Colorado","color":"#A0522D","force":"Medium-Full","wrapper":"Colorado","vitolas":[],"story":"Fünf Formate, vom Amanecer bis zum Alba, vorgestellt auf der Intertabac 2026 zu Ehren des Gründers."},{"name":"Alejandro Mata Maduro","color":"#4A3728","force":"Medium-Full","wrapper":"Maduro","vitolas":[],"story":"Drei Formate, vom Legado bis zum Linaje, für März 2027 auf dem internationalen Markt erwartet."}]',
        'Alfambra是亚历杭德罗·马塔的品牌，他是来自马拉加的西班牙企业家，当时是Havana Club朗姆酒的经销商。他对雪茄的热情促使他在2005年参加Festival del Habano，在那里结识了古巴烟草种植者阿莱汉德罗·罗巴伊纳。2007年，马塔在埃斯特利开设了一家小工厂，两对卷烟师在那里加工一种来自古巴雷梅迪奥斯、名为La Flor de San Luis的烟叶，随后于2015年推出Alfambra品牌——媒体认为这个名字与格拉纳达的阿尔罕布拉宫有关——首款产品是橙色烟圈的medium-filler雪茄，年产3万支。工厂名为Tabacalera Alfambra，在尼加拉瓜的Páginas Amarillas名录中列于埃斯特利名下。其自有土地，包括普韦布洛努埃沃的两处庄园，在尼加拉瓜共计超过五十公顷，据介绍日产量接近6000支，销往十二个欧洲国家。

El Brujito是一款在品牌创立三年后推出的longfiller，亚历杭德罗·马塔透露已售出84万支。Boutique产品线，其中包括一款Gran Toro，构成目录的补充。一条名为Alejandro Mata的新产品线已在Intertabac 2026展出，预计2027年3月进入国际市场，向创始人致敬：colorado茄衣五种规格，maduro茄衣三种规格。',
        '[{"name":"El Brujito","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"品牌创立三年后推出的longfiller；亚历杭德罗·马塔透露已售出84万支。"},{"name":"Alfambra Boutique","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"目录中的产品线，其中包括一款Gran Toro。"},{"name":"Alejandro Mata Colorado","color":"#A0522D","force":"Medium-Full","wrapper":"Colorado","vitolas":[],"story":"五种规格，从Amanecer到Alba，于Intertabac 2026展出，向创始人致敬。"},{"name":"Alejandro Mata Maduro","color":"#4A3728","force":"Medium-Full","wrapper":"Maduro","vitolas":[],"story":"三种规格，从Legado到Linaje，预计2027年3月进入国际市场。"}]',
        'Alfambra هي علامة أليخاندرو ماتا، رجل الأعمال الإسباني من مالقة، الذي كان آنذاك موزّعًا لرَم Havana Club. وقادَه شغفه بالسيجار إلى Festival del Habano سنة 2005، حيث التقى المزارع الكوبي أليخاندرو روباينا. وفي 2007 افتتح ماتا مصنعًا صغيرًا في إستيلي، حيث عمل زوجان من اللفّافين على تبغ من ريميديوس بكوبا يُدعى La Flor de San Luis، قبل أن يُطلق سنة 2015 علامة Alfambra — وهو اسم تربطه الصحافة بقصر الحمراء في غرناطة — بسيجار أوّل من فئة medium-filler بشريط برتقالي، يُنتَج بمعدّل 30000 قطعة سنويًا. ويظهر المصنع، Tabacalera Alfambra، في إستيلي ضمن دليل Páginas Amarillas النيكاراغوي. وتتجاوز أراضيه الخاصة، ومنها ضيعتان في بويبلو نويبو، خمسين هكتارًا في نيكاراغوا، ويُقال إنّ الإنتاج يقترب من 6000 سيجار يوميًا، تُباع في اثنتي عشرة دولة أوروبية.

أمّا El Brujito، وهو longfiller أُطلق بعد ثلاث سنوات من انطلاقة العلامة، فقد بِيع منه 840000 قطعة، بحسب ما قاله أليخاندرو ماتا. ويكمل الكتالوجَ خطّ Boutique، ومنه طراز Gran Toro. وقُدّم في Intertabac 2026 خطّ جديد يحمل اسم Alejandro Mata يُنتظر طرحه في السوق الدولية في مارس 2027، تكريمًا للمؤسّس: غلاف colorado بخمسة مقاسات، وغلاف maduro بثلاثة مقاسات.',
        '[{"name":"El Brujito","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"longfiller أُطلق بعد ثلاث سنوات من انطلاقة العلامة؛ بِيع منه 840000 سيجار، بحسب ما قاله أليخاندرو ماتا."},{"name":"Alfambra Boutique","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خطّ ضمن الكتالوج، ومنه طراز Gran Toro."},{"name":"Alejandro Mata Colorado","color":"#A0522D","force":"Medium-Full","wrapper":"Colorado","vitolas":[],"story":"خمسة مقاسات، من Amanecer إلى Alba، كُشف عنها في Intertabac 2026 تكريمًا للمؤسّس."},{"name":"Alejandro Mata Maduro","color":"#4A3728","force":"Medium-Full","wrapper":"Maduro","vitolas":[],"story":"ثلاثة مقاسات، من Legado إلى Linaje، يُنتظر طرحها في السوق الدولية في مارس 2027."}]')
