-- ── Casa de Alegria ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Casa de Alegria',
        'nicaragua',
        '2004 — Molina et Westerwick, Estelí',
        'Usine propre — Casa de Alegria S.A. (Tabacalera), Estelí (Nicaragua)',
        'cigarworld.de « Casa de Alegria » (en allemand ; consulté 2026-09-24 : maison fondée en octobre 2004 à Estelí par Maritza Molina, CEO de formation psychologue, et Ralf Westerwick, maître assembleur géographe originaire de Gummersbach ; production dite premium longfiller fait main ; gammes Edición Limitada Rico, terreuse et épicée, fermentée au moins douze mois, et Edición Limitada Suave, plus douce et crémeuse sous cape Connecticut) ; cigar-wiki.com « Casa de Alegria » (consulté 2026-09-23 : cigares roulés dans la manufacture d''Estelí en coopération avec Cigarworld/Tabac Benden, capacité d''environ 8000 cigares par mois) ; cigarworld.de « Rosa Nicaragua – Cigars | Cigarworld.de » (consulté 2026-09-24 : Rosa Nicaragua, marque fondée par Ralf Westerwick, non détenue par Casa de Alegria elle-même, liée à Cigarworld par un lien personnel entre son fondateur et la direction du revendeur, qui en achète régulièrement une quantité fixe ; trois lignes — Jalapa, Estelí, Connecticut) ; hacico.de « Rosa Nicaragua » (consulté 2026-09-24 : confirme les trois lignes et une politique dite de commerce équitable — achat immédiat de la récolte, salaires supérieurs à la moyenne)',
        '["Rosa Nicaragua"]',
        'Casa de Alegria S.A. est fondée en octobre 2004 à Estelí par Maritza Molina, psychologue de formation devenue directrice générale, et Ralf Westerwick, géographe originaire de Gummersbach (Allemagne) devenu maître assembleur — une reconversion professionnelle à deux, dit le distributeur allemand Cigarworld. La maison roule dans sa propre tabacalera d''Estelí ce que ce distributeur qualifie de premium longfiller fait main. Les gammes Edición Limitada Rico et Edición Limitada Suave restent au catalogue de plusieurs cavistes allemands en 2026.

À la même fabrique, Ralf Westerwick a aussi lancé, en son nom propre, la marque Rosa Nicaragua — non détenue par Casa de Alegria elle-même, précise Cigarworld, qui évoque un lien personnel entre Westerwick et la direction du revendeur, et achète régulièrement une quantité fixe de la production. Trois lignes la composent : la Jalapa, sous cape indonésienne et dite douce, l''Estelí, plus relevée en tabac nicaraguayen, et la Connecticut, sous cape dorée et crémeuse. La marque revendique des pratiques de commerce équitable — achat immédiat de la récolte, salaires dits supérieurs à la moyenne.',
        '[{"name":"Edición Limitada Rico","color":"#8B5A2B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Notes terreuses et épicées, fermentation d''au moins douze mois, dit Cigarworld."},{"name":"Edición Limitada Suave","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut","vitolas":[],"story":"Nettement plus douce et crémeuse que la Rico, sous cape Connecticut, dit Cigarworld."}]',
        'Casa de Alegria S.A. was founded in October 2004 in Estelí by Maritza Molina, a trained psychologist who became managing director, and Ralf Westerwick, a geographer from Gummersbach, Germany, who became master blender — a joint career change, says German distributor Cigarworld. The house rolls, in its own tabacalera in Estelí, what this distributor describes as a handmade premium longfiller. The Edición Limitada Rico and Edición Limitada Suave lines remain in the catalogue of several German tobacconists in 2026.

At the same factory, Ralf Westerwick has also launched, under his own name, the Rosa Nicaragua brand — not owned by Casa de Alegria itself, Cigarworld notes, pointing to a personal tie between Westerwick and the retailer''s management, which regularly buys a fixed quantity of the output. Three lines make it up: the Jalapa, under an Indonesian wrapper and said to be mild, the Estelí, sharper with Nicaraguan tobacco, and the Connecticut, under a golden, creamy wrapper. The brand claims fair-trade practices — immediate purchase of the harvest, wages said to be above average.',
        '[{"name":"Edición Limitada Rico","color":"#8B5A2B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Earthy, spicy notes, fermented for at least twelve months, says Cigarworld."},{"name":"Edición Limitada Suave","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut","vitolas":[],"story":"Distinctly milder and creamier than the Rico, under a Connecticut wrapper, says Cigarworld."}]',
        'Casa de Alegria S.A. se funda en octubre de 2004 en Estelí de la mano de Maritza Molina, psicóloga de formación convertida en directora general, y Ralf Westerwick, geógrafo originario de Gummersbach (Alemania) convertido en maestro ligador — un cambio de carrera profesional a dos, según el distribuidor alemán Cigarworld. La casa lía en su propia tabacalera de Estelí lo que este distribuidor califica de longfiller premium hecho a mano. Las gamas Edición Limitada Rico y Edición Limitada Suave siguen en el catálogo de varias tiendas especializadas alemanas en 2026.

En la misma fábrica, Ralf Westerwick también lanzó, a título personal, la marca Rosa Nicaragua — no propiedad de la propia Casa de Alegria, precisa Cigarworld, que menciona un vínculo personal entre Westerwick y la dirección del revendedor, el cual compra con regularidad una cantidad fija de la producción. La componen tres líneas: la Jalapa, con capa indonesia y calificada de suave, la Estelí, más viva en tabaco nicaragüense, y la Connecticut, con capa dorada y cremosa. La marca reivindica prácticas de comercio justo — compra inmediata de la cosecha, salarios dichos superiores a la media.',
        '[{"name":"Edición Limitada Rico","color":"#8B5A2B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Notas terrosas y especiadas, fermentación de al menos doce meses, según Cigarworld."},{"name":"Edición Limitada Suave","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut","vitolas":[],"story":"Claramente más suave y cremosa que la Rico, con capa Connecticut, según Cigarworld."}]',
        'Casa de Alegria S.A. wurde im Oktober 2004 in Estelí von Maritza Molina, einer ausgebildeten Psychologin, die Geschäftsführerin wurde, und Ralf Westerwick, einem Geografen aus Gummersbach, der zum Chefmischer wurde, gegründet — ein gemeinsamer Berufswechsel, so der deutsche Händler Cigarworld. Das Haus rollt in seiner eigenen Tabacalera in Estelí, was dieser Händler als handgerollten Premium-Longfiller bezeichnet. Die Linien Edición Limitada Rico und Edición Limitada Suave stehen 2026 weiterhin im Katalog mehrerer deutscher Zigarrenhändler.

In derselben Fabrik hat Ralf Westerwick zudem unter eigenem Namen die Marke Rosa Nicaragua lanciert — die nicht Casa de Alegria selbst gehört, wie Cigarworld anmerkt, das auf eine persönliche Verbindung zwischen Westerwick und der Geschäftsführung des Händlers verweist, der regelmäßig eine feste Menge der Produktion abnimmt. Drei Linien bilden sie: die Jalapa, mit indonesischem Deckblatt und als mild beschrieben, die Estelí, kräftiger durch nicaraguanischen Tabak, und die Connecticut, mit goldenem, cremigem Deckblatt. Die Marke beansprucht faire Handelspraktiken — sofortiger Ankauf der Ernte, Löhne, die als überdurchschnittlich bezeichnet werden.',
        '[{"name":"Edición Limitada Rico","color":"#8B5A2B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Erdige, würzige Noten, mindestens zwölf Monate fermentiert, so Cigarworld."},{"name":"Edición Limitada Suave","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut","vitolas":[],"story":"Deutlich milder und cremiger als die Rico, mit Connecticut-Deckblatt, so Cigarworld."}]',
        'Casa de Alegria S.A.于2004年10月在埃斯特利成立，创始人是学心理学出身、后成为总经理的玛丽察·莫利纳，以及来自德国古默斯巴赫、后成为首席调配师的地理学家拉尔夫·韦斯特维克——据德国经销商Cigarworld介绍，这是两人共同的职业转型。该品牌在自有的埃斯特利tabacalera中卷制该经销商所称的手工优质longfiller雪茄。Edición Limitada Rico和Edición Limitada Suave两条产品线截至2026年仍在多家德国雪茄专卖店的目录中。

在同一家工厂，拉尔夫·韦斯特维克还以个人名义推出了Rosa Nicaragua品牌——据Cigarworld说明，该品牌并非Casa de Alegria自身所有，并提到韦斯特维克与这家经销商管理层之间存在私人关系，该经销商会定期购买固定数量的产品。该品牌由三条产品线组成：Jalapa，茄衣为印尼产、口味清淡；Estelí，采用尼加拉瓜烟叶、风味更浓烈；以及Connecticut，茄衣呈金黄色、口感绵密。该品牌宣称遵循公平贸易做法——即时收购烟叶、工资据称高于平均水平。',
        '[{"name":"Edición Limitada Rico","color":"#8B5A2B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"带有泥土与香料风味，发酵至少十二个月，据Cigarworld介绍。"},{"name":"Edición Limitada Suave","color":"#C9A96E","force":"Mild-Medium","wrapper":"康涅狄格","vitolas":[],"story":"比Rico明显更温和、更绵密，茄衣为康涅狄格，据Cigarworld介绍。"}]',
        'تأسّست Casa de Alegria S.A. في أكتوبر 2004 في إستيلي على يد ماريتسا مولينا، أخصائية نفسية بالتكوين أصبحت مديرة عامة، ورالف فيسترفيك، جغرافي من غومرسباخ بألمانيا أصبح كبير الخلّاطين — وهو تحوّل مهني مشترك، وفق الموزّع الألماني Cigarworld. وتُلفّ الدار في تاباكاليرا خاصة بها في إستيلي ما يصفه هذا الموزّع بأنّه longfiller فاخر مصنوع يدويًا. ولا يزال خطّا Edición Limitada Rico وEdición Limitada Suave ضمن كتالوجات عدّة متاجر تبغ ألمانية سنة 2026.

وفي المصنع نفسه، أطلق رالف فيسترفيك أيضًا، باسمه الخاص، علامة Rosa Nicaragua — وهي غير مملوكة لـCasa de Alegria نفسها، كما توضّح Cigarworld، التي تشير إلى صلة شخصية بين فيسترفيك وإدارة الموزّع، الذي يشتري بانتظام كمّية ثابتة من الإنتاج. وتتألّف من ثلاثة خطوط: Jalapa، بغلاف إندونيسي وتوصف بأنّها لطيفة؛ وEstelí، أشدّ حدّة بتبغ نيكاراغوي؛ وConnecticut، بغلاف ذهبي وقوام كريمي. وتدّعي العلامة اتّباع ممارسات تجارة عادلة — شراء فوري للمحصول، وأجور يُقال إنّها أعلى من المتوسط.',
        '[{"name":"Edición Limitada Rico","color":"#8B5A2B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"بنكهات ترابية وحارّة، وتخمير لا يقلّ عن اثني عشر شهرًا، وفق Cigarworld."},{"name":"Edición Limitada Suave","color":"#C9A96E","force":"Mild-Medium","wrapper":"كونيتيكت","vitolas":[],"story":"ألطف وأنعم قوامًا بوضوح من Rico، بغلاف كونيتيكت، وفق Cigarworld."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Don Fidel ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Don Fidel',
        'nicaragua',
        'Non précisée — Justo Rico, Estelí',
        'Chez la Tabacalera de la famille Fidel Olivas (maître rouleur Don Fidel Olivas), Estelí (Nicaragua)',
        'cigarworld.de « Don Fidel – Cigars | Cigarworld.de » (consulté 2026-09-24 : marque du détaillant barcelonais Justo Rico, roulée par la famille Fidel Olivas à Estelí ; ligne El Legado ; Rico fait aussi rouler à la même fabrique une autre marque, Vedado Flat Black, présentée comme distincte de Don Fidel) ; noblego.de « Don Fidel El Legado Zigarren » (en allemand ; consulté 2026-09-24 : maître assembleur Don Fidel Olivas en personne, cigares dits roulés à la main (handgerollt), cape équatorienne H2000, sous-cape nicaraguayenne, tabacs vieillis au moins trois ans, force medium, quatre formats — Robusto, Toro, Gordo, Toro Grande) ; cigarconexion.in « Don Fidel El Legado Robusto » (date non précisée : catégorie Hand Made Cigars, cape et sous-cape Habano, garnissage Nicaragua/République dominicaine, vieilli 36 mois) ; cigarconexion.in « Vedado Flat Black – Top Nicaraguan Cigars » (consulté 2026-09-24 : Vedado Flat Black, autre marque de Justo Rico roulée à la même tabacalera de la famille Fidel Olivas, cape mexicaine San Andrés, sous-cape Habano nicaraguayen, tripe d''Estelí, de Condega et de Jalapa, vieillie au moins 48 mois, force medium)',
        '["Vedado Flat Black"]',
        'Don Fidel est la marque du détaillant barcelonais Justo Rico, propriétaire de plusieurs boutiques de tabac en Catalogne, qui en a confié le roulage à la tabacalera de la famille Fidel Olivas, à Estelí — le maître assembleur, dit le caviste allemand Cigarworld, est Don Fidel Olivas en personne. La presse spécialisée indépendante ne couvre pas la marque ; ce qu''on en sait vient de deux revendeurs, Cigarworld et Noblego, qui la disent roulée entièrement à la main. La ligne El Legado, en quatre formats — Robusto, Toro, Gordo et Toro Grande —, assemble une tripe nicaraguayenne vieillie au moins trois ans, sous une cape équatorienne H2000 et une sous-cape nicaraguayenne selon Noblego, ou sous une cape et une sous-cape Habano avec une tripe mêlant Nicaragua et République dominicaine selon un revendeur indien, pour un profil épicé et boisé que les deux disent medium.

À la même fabrique, Justo Rico fait aussi rouler une autre marque, que Cigarworld présente comme distincte de Don Fidel : Vedado Flat Black, sous cape mexicaine San Andrés, tripe d''Estelí, de Condega et de Jalapa, vieillie au moins quarante-huit mois. Aucune date de création n''a été trouvée pour Don Fidel elle-même ; la ligne El Legado reste en vente chez plusieurs cavistes européens en 2026, sans actualité de presse datée.',
        '[{"name":"El Legado","color":"#A0522D","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Quatre formats — Robusto, Toro, Gordo, Toro Grande —, tripe nicaraguayenne vieillie au moins trois ans ; cape équatorienne H2000 selon Noblego, Habano selon un revendeur indien."}]',
        'Don Fidel is the brand of Barcelona retailer Justo Rico, owner of several tobacco shops in Catalonia, who entrusted its rolling to the tabacalera of the Fidel Olivas family, in Estelí — the master blender, says German tobacconist Cigarworld, is Don Fidel Olivas himself. The independent specialist press does not cover the brand; what is known comes from two retailers, Cigarworld and Noblego, which describe it as rolled entirely by hand. The El Legado line, in four sizes — Robusto, Toro, Gordo and Toro Grande —, blends a Nicaraguan filler aged at least three years, under an Ecuadorian H2000 wrapper and a Nicaraguan binder according to Noblego, or under a Habano wrapper and binder with a filler mixing Nicaragua and the Dominican Republic according to an Indian retailer, for a spicy, woody profile both call medium.

At the same factory, Justo Rico also has another brand rolled, which Cigarworld presents as distinct from Don Fidel: Vedado Flat Black, under a Mexican San Andrés wrapper, filler from Estelí, Condega and Jalapa, aged at least forty-eight months. No founding date has been found for Don Fidel itself; the El Legado line remains on sale at several European tobacconists in 2026, with no dated press coverage.',
        '[{"name":"El Legado","color":"#A0522D","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Four sizes — Robusto, Toro, Gordo, Toro Grande —, Nicaraguan filler aged at least three years; Ecuadorian H2000 wrapper according to Noblego, Habano according to an Indian retailer."}]',
        'Don Fidel es la marca del minorista barcelonés Justo Rico, propietario de varias tiendas de tabaco en Cataluña, que confió su liado a la tabacalera de la familia Fidel Olivas, en Estelí — el maestro ligador, según el estanquero alemán Cigarworld, es el propio Don Fidel Olivas. La prensa especializada independiente no cubre la marca; lo que se sabe procede de dos revendedores, Cigarworld y Noblego, que la describen como liada enteramente a mano. La línea El Legado, en cuatro formatos — Robusto, Toro, Gordo y Toro Grande —, combina una tripa nicaragüense envejecida al menos tres años, bajo una capa ecuatoriana H2000 y un capote nicaragüense según Noblego, o bajo una capa y un capote Habano con una tripa que mezcla Nicaragua y República Dominicana según un revendedor indio, para un perfil especiado y amaderado que ambos califican de medium.

En la misma fábrica, Justo Rico hace liar también otra marca, que Cigarworld presenta como distinta de Don Fidel: Vedado Flat Black, con capa mexicana San Andrés, tripa de Estelí, Condega y Jalapa, envejecida al menos cuarenta y ocho meses. No se ha encontrado fecha de creación para el propio Don Fidel; la línea El Legado sigue a la venta en varias tiendas especializadas europeas en 2026, sin actualidad de prensa fechada.',
        '[{"name":"El Legado","color":"#A0522D","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Cuatro formatos — Robusto, Toro, Gordo, Toro Grande —, tripa nicaragüense envejecida al menos tres años; capa ecuatoriana H2000 según Noblego, Habano según un revendedor indio."}]',
        'Don Fidel ist die Marke des Barceloneser Einzelhändlers Justo Rico, Inhaber mehrerer Tabakläden in Katalonien, der das Rollen der Tabacalera der Familie Fidel Olivas in Estelí anvertraute — der Chefmischer, so der deutsche Zigarrenhändler Cigarworld, ist Don Fidel Olivas persönlich. Die unabhängige Fachpresse berichtet nicht über die Marke; was man weiß, stammt von zwei Händlern, Cigarworld und Noblego, die sie als vollständig handgerollt bezeichnen. Die Linie El Legado, in vier Formaten — Robusto, Toro, Gordo und Toro Grande —, vereint eine mindestens drei Jahre gereifte nicaraguanische Einlage unter einem ecuadorianischen H2000-Deckblatt und einem nicaraguanischen Umblatt laut Noblego, oder unter einem Habano-Deckblatt und -Umblatt mit einer Einlage aus Nicaragua und der Dominikanischen Republik laut einem indischen Händler, für ein würzig-holziges Profil, das beide als medium bezeichnen.

In derselben Fabrik lässt Justo Rico auch eine weitere Marke rollen, die Cigarworld als eigenständig neben Don Fidel darstellt: Vedado Flat Black, mit mexikanischem San-Andrés-Deckblatt, Einlage aus Estelí, Condega und Jalapa, mindestens achtundvierzig Monate gereift. Für Don Fidel selbst wurde kein Gründungsdatum gefunden; die Linie El Legado bleibt 2026 bei mehreren europäischen Zigarrenhändlern erhältlich, ohne datierte Presseberichterstattung.',
        '[{"name":"El Legado","color":"#A0522D","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Vier Formate — Robusto, Toro, Gordo, Toro Grande —, mindestens drei Jahre gereifte nicaraguanische Einlage; ecuadorianisches H2000-Deckblatt laut Noblego, Habano laut einem indischen Händler."}]',
        'Don Fidel是巴塞罗那零售商Justo Rico的品牌，他在加泰罗尼亚拥有多家烟草店，并将卷制工作交给了埃斯特利的Fidel Olivas家族tabacalera——据德国雪茄专卖店Cigarworld介绍，首席调配师正是Don Fidel Olivas本人。独立专业媒体均未报道该品牌；已知信息来自两家经销商Cigarworld和Noblego，两者均称其完全手工卷制。El Legado产品线共有四种规格——Robusto、Toro、Gordo和Toro Grande——采用陈化至少三年的尼加拉瓜茄芯，据Noblego介绍茄衣为厄瓜多尔H2000、茄套为尼加拉瓜产，另据一家印度经销商介绍则是habano茄衣和茄套、茄芯混合尼加拉瓜和多米尼加共和国烟叶，呈现两者都称为中等力度的辛香与木质风味。

在同一家工厂，Justo Rico还卷制另一个品牌，Cigarworld将其列为独立于Don Fidel之外：Vedado Flat Black，茄衣为墨西哥圣安德烈斯，茄芯来自埃斯特利、孔德加和哈拉帕，陈化至少四十八个月。Don Fidel本身的创立日期尚未找到；El Legado产品线截至2026年仍在多家欧洲雪茄专卖店有售，但没有具体日期的媒体报道。',
        '[{"name":"El Legado","color":"#A0522D","force":"Medium","wrapper":"未公开","vitolas":[],"story":"四种规格——Robusto、Toro、Gordo、Toro Grande——尼加拉瓜茄芯陈化至少三年；据Noblego介绍茄衣为厄瓜多尔H2000，另据一家印度经销商介绍为habano。"}]',
        'Don Fidel هي علامة تاجر التجزئة البرشلوني خوستو ريكو، مالك عدّة متاجر تبغ في كتالونيا، الذي عهد بلفّها إلى تاباكاليرا عائلة Fidel Olivas في إستيلي — وكبير الخلّاطين، وفق متجر التبغ الألماني Cigarworld، هو Don Fidel Olivas شخصيًا. ولا تغطّي الصحافةُ المتخصّصةُ المستقلّةُ العلامةَ؛ وما يُعرف عنها يأتي من موزّعين اثنين، Cigarworld وNoblego، يصفانها بأنّها مُلفوفة يدويًا بالكامل. ويجمع خطّ El Legado، بأربعة مقاسات — Robusto وToro وGordo وToro Grande —، حشوة نيكاراغوية معتّقة ثلاث سنوات على الأقلّ، تحت غلاف H2000 إكوادوري وورقة رابطة نيكاراغوية وفق Noblego، أو تحت غلاف وورقة رابطة من habano مع حشوة تمزج نيكاراغوا وجمهورية الدومينيكان وفق موزّع هندي، بملمح حارّ وخشبي يصفه الاثنان بأنّه متوسط القوة.

وفي المصنع نفسه، يُلفّ خوستو ريكو أيضًا علامة أخرى تقدّمها Cigarworld بوصفها منفصلة عن Don Fidel: Vedado Flat Black، بغلاف سان أندريس مكسيكي، وحشوة من إستيلي وكونديغا وخالابا، معتّقة ثمانية وأربعين شهرًا على الأقلّ. ولم يُعثر على تاريخ تأسيس لعلامة Don Fidel نفسها؛ ولا يزال خطّ El Legado يُباع لدى عدّة متاجر تبغ أوروبية سنة 2026، من دون أخبار صحفية مؤرّخة.',
        '[{"name":"El Legado","color":"#A0522D","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"أربعة مقاسات — Robusto وToro وGordo وToro Grande —، حشوة نيكاراغوية معتّقة ثلاث سنوات على الأقلّ؛ غلاف H2000 إكوادوري وفق Noblego، أو habano وفق موزّع هندي."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

