INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Baron Ullmann','Belmore','Bock y Ca.','Capadura','Chateau Diadem','Notorious','Simon Beltre','Vallejuelo','Stauffenberg','El Gaucho','Alfambra','Casa de Alegria','Don Fidel')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 239';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 239','systeme','recensement_8_fiches','marque',0,
   'dominican : Baron Ullmann, Belmore, Bock y Ca., Capadura, Chateau Diadem, Notorious, Simon Beltre, Vallejuelo'),
  (NULL,'migration 239','systeme','recensement_8_fiches','marque',0,
   'honduras : Stauffenberg'),
  (NULL,'migration 239','systeme','recensement_8_fiches','marque',0,
   'indonesia : El Gaucho'),
  (NULL,'migration 239','systeme','recensement_8_fiches','marque',0,
   'nicaragua : Alfambra, Casa de Alegria, Don Fidel');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Baron Ullmann','Belmore','Bock y Ca.','Capadura','Chateau Diadem','Notorious','Simon Beltre','Vallejuelo','Stauffenberg','El Gaucho','Alfambra','Casa de Alegria','Don Fidel')) = 13 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Baron Ullmann"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Belmore"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Bock y Ca."') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Capadura"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Chateau Diadem"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Notorious"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Simon Beltre"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Vallejuelo"') FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Stauffenberg"') FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"El Gaucho"') FROM `producer_countries` WHERE `id` = 'indonesia') AS indonesia_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Alfambra"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Casa de Alegria"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Don Fidel"') FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('Baron Ullmann','Belmore','Bock y Ca.','Capadura','Chateau Diadem','Notorious','Simon Beltre','Vallejuelo','Stauffenberg','El Gaucho','Alfambra','Casa de Alegria','Don Fidel')) = 130 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 239') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
